-- US admission requirements from each school's official pages (checked 13 Nov 2026), wave 1 (136 schools with the most programs). Needs step181.
update schools set admission_info = $q${"ug": "Apply through the Common App. You must meet minimum preparation in six subject areas (CADR). SAT or ACT is generally not required. Interviews, recommendation letters and portfolios are not considered.", "english": "Minimum TOEFL iBT 76 (tests before Jan 21, 2026) or 4.0 (new scale), IELTS 6.0, or Duolingo 110. You are exempt only if both primary and secondary school were in Australia, Canada, the UK, Ireland, New Zealand or the US. Another option is a B average in English plus SAT EBRW 580 or ACT English 22.", "how_to_apply": "Apply for autumn through the Common App (opens Aug 15). Submit your courses and grades in STARS after applying. International first-year applications are not accepted for winter or spring. UW says federal and university rules severely limit financial aid for international students, so no international scholarship is listed.", "deadlines": "Nov 15. Decisions are released March 1 to 15.", "application_fee": "$95, nonrefundable. Fee waivers are not available.", "documents": "Common App with essay (650 words max), STARS self-reported record, school transcript (unofficial scan accepted at application, final official transcript if you enroll), English test scores.", "fees_link": "https://www.washington.edu/financialaid/getting-started/eligibility/international-students/", "sources": ["https://admit.washington.edu/Apply/freshman/how-to-apply", "https://admit.washington.edu/apply/first-year/how-to-apply/english-proficiency/", "https://www.washington.edu/financialaid/getting-started/eligibility/international-students/"]}$q$::jsonb, admission_link = $q$https://www.washington.edu/financialaid/getting-started/eligibility/international-students/$q$, admission_checked = '2026-11-13' where id = 'c0754f53-7d88-4d87-929f-7fb5aa69e52f' and country = 'United States';
update schools set admission_info = $q${"ug": "High school GPA of 3.00 or higher (B or better) and a completed high school diploma or certificate. For non-US schools, four years of math and three years of lab science are expected. Some programs ask for a higher GPA.", "english": "Most majors: IELTS 6.0, TOEFL iBT 61 (3.5 new scale), Duolingo 95, PTE 53. Engineering: IELTS 6.5, TOEFL 79 (4 new scale). Nursing BSN: IELTS 6.5, TOEFL 76. Journalism (Cronkite): IELTS 7.0, TOEFL 100. Conditional admission is possible for students who are not yet English proficient (offer valid up to three semesters).", "how_to_apply": "Apply with ASU's own application or the Common App (only one). Send official records and test scores directly to ASU. You need an I-20 before applying for an F-1 visa.", "deadlines": "Fall priority deadline Jan 15. Spring priority deadline Nov 1.", "application_fee": "$90 for international nonresidents, nonrefundable.", "documents": "Application, official transcripts from every school (certified English translation if needed), English test results, attested original school records with official seal or signature. SAT or ACT is optional.", "fees_link": "https://admission.asu.edu/cost-aid/international", "sources": ["https://admission.asu.edu/apply/international/first-year", "https://admission.asu.edu/cost-aid/international"]}$q$::jsonb, admission_link = $q$https://admission.asu.edu/cost-aid/international$q$, admission_checked = '2026-11-13' where id = '2faf4015-5e4c-4b1e-a4f4-e1c351fed744' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply through MyPennState or the Common App. Send a STARS record or official transcripts from the last three years of study. SAT or ACT is optional.", "english": "Minimum Duolingo 120, TOEFL iBT 80 (4.5 on the new scale), IELTS Academic 6.5, SAT EBRW 570, or ACT English 24. Scores must be under two years old. TOEFL MyBest is not accepted. Other options: four years at a US high school or Penn State IECP certification.", "how_to_apply": "Apply online and send documents as official originals or certified copies. Non-English documents need a certified line by line English translation. The international admission page does not list any international scholarships.", "documents": "Application, STARS record or official transcripts (last three years), proof of English proficiency. Documents must be official originals or certified copies, not notarized copies.", "fees_link": "https://www.psu.edu/costs-aid", "sources": ["https://www.psu.edu/resources/international-students/admission-requirements"]}$q$::jsonb, admission_link = $q$https://www.psu.edu/costs-aid$q$, admission_checked = '2026-11-13' where id = '821aec70-3a01-404b-93e4-750ecf4a271b' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply to the Columbus campus through the Common App. SAT or ACT scores are required. Send grade 9 to 12 school records. Up to two recommendation letters are optional.", "english": "Minimum TOEFL 79 (4.0 on the new scale), IELTS 6.5, Duolingo 120, SAT EBRW 550, or ACT English 21. Alternatives: three years at a US regionally accredited high school, or citizenship or a degree from an approved country or region.", "how_to_apply": "Apply through the Common App with fee and all materials. Proof of financial support is needed only if admitted. The merit scholarships page states that international students are not eligible, so no international merit scholarship is listed.", "deadlines": "Early action Nov 1 (decision Jan 22). Regular decision Jan 15 (decision Mar 5). Spring 2027: Oct 1, 2026.", "documents": "Common App, school transcripts (grades 9 to 12, sent by counselor or email to ugdocs@osu.edu), official SAT or ACT, English proficiency scores, certified English translations, proof of financial support if admitted.", "fees_link": "https://undergrad.osu.edu/cost-and-aid/merit-based-Scholarships", "sources": ["https://undergrad.osu.edu/apply/international-freshmen/apply-step-by-step", "https://undergrad.osu.edu/cost-and-aid/merit-based-Scholarships"]}$q$::jsonb, admission_link = $q$https://undergrad.osu.edu/cost-and-aid/merit-based-Scholarships$q$, admission_checked = '2026-11-13' where id = '7dfab406-4c12-4582-99ed-22ff85a69e80' and country = 'United States';
update schools set admission_info = $q${"ug": "International students follow the same application process as US students (first-year or transfer). You must prove English proficiency if you attended school in a non-English-speaking country.", "english": "Minimum IELTS 6.5, TOEFL iBT 79 (4 on the new scale), Duolingo 110, PTE 60, SAT EBRW 580, or ACT English 21. Scores must be within 2 years. Exempt with 3 years of regular English classes (grade C or better) at an accredited American or IB high school, or Cambridge IGCSE or O Level English grade C.", "how_to_apply": "Apply as a first-year or transfer student. All documents must be in English (use a certified translation). Scholarship consideration is automatic at admission for the Global Wildcat Award.", "documents": "Transcripts in English (certified translation), official English test report sent from the testing center.", "fees_link": "https://everywhere.arizona.edu/cost/main-campus", "sources": ["https://www.arizona.edu/admissions/undergraduate/international", "https://everywhere.arizona.edu/cost/main-campus"]}$q$::jsonb, admission_link = $q$https://everywhere.arizona.edu/cost/main-campus$q$, admission_checked = '2026-11-13' where id = 'f74b79a7-dab1-4945-9cec-bfb9c530bafe' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the Common App, plus a self-reported academic record. No essay or recommendation letters are required. SAT or ACT is optional.", "english": "Minimums for Spring 2027: TOEFL iBT 4.5 (new scale, no MyBest), IELTS Academic 6.5, PTE 59, CAE C1 Advanced 180, Duolingo 120. Conditional admission is offered for fall only.", "how_to_apply": "Apply with the Common App and pay the fee. Provide a Certification of Finances form if you need a US study visa. Official final transcripts must be sent in a sealed envelope before enrollment. Applicants who finish by the deadlines are considered for scholarships without a separate form.", "deadlines": "Early Action I Nov 1 (decision by Jan 31). Early Action II Dec 1 (by Feb 28). Regular Jan 1 (by Mar 31).", "application_fee": "$55, nonrefundable.", "documents": "Common App, self-reported academic record, English test scores, Certification of Finances (for visa applicants), official final transcripts if you enroll.", "fees_link": "https://admissions.tc.umn.edu/admissions/international-freshman-admissions-timeline", "sources": ["https://admissions.tc.umn.edu/apply/application-checklist/application-checklist-international-freshman", "https://admissions.tc.umn.edu/admissions/international-admission/english-proficiency-information", "https://admissions.tc.umn.edu/admissions/international-freshman-admissions-timeline"]}$q$::jsonb, admission_link = $q$https://admissions.tc.umn.edu/admissions/international-freshman-admissions-timeline$q$, admission_checked = '2026-11-13' where id = '89d9f09f-6ba5-4a78-9f3a-2689a48250f5' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply through the Common App or ApplyTexas. Texas A&M is test optional. Essays are required (750 word personal essay, 250 word life-event response and short answers). The first two recommendation letters received are considered.", "english": "One of: TOEFL iBT 80 (before Jan 21, 2026) or 4.5 overall with 4.0 per section (after), TOEFL Essentials 8.5, IELTS Academic 6.0, SAT EBRW 560, ACT English 21, or four years of US high school. Some countries are exempt. TOEFL MyBest and IELTS General are not accepted.", "how_to_apply": "Apply through the Common App or ApplyTexas and submit a STARS record. Fee waivers are not available to international applicants. The admissions page lists university and third-party scholarships for international students but gives no names or amounts.", "deadlines": "Fall: Dec 1 (documents and STARS by Dec 15). Spring: Oct 15.", "application_fee": "$90, nonrefundable.", "documents": "Application, essays, STARS record, official transcripts if already graduated (original seal or sealed envelope, certified English translation), English test scores.", "fees_link": "https://admissions.tamu.edu/resources/future-students/international-students", "sources": ["https://admissions.tamu.edu/apply/international/international-freshman.html", "https://admissions.tamu.edu/resources/future-students/international-students"]}$q$::jsonb, admission_link = $q$https://admissions.tamu.edu/resources/future-students/international-students$q$, admission_checked = '2026-11-13' where id = 'e1ecb70e-ceee-4e55-9260-15f84bddb051' and country = 'United States';
update schools set admission_info = $q${"ug": "No minimum requirements, but admission is competitive. MSU reviews grades, course strength, class rank, test results and English proficiency.", "english": "Regular admission: TOEFL iBT 79 (4 on the new scale), IELTS 6.5, Duolingo 110, PTE 53, SAT EBRW 510 (with total 1110), ACT English 18 (with composite 23). Provisional admission is possible with TOEFL 60 to 78, IELTS 6.0 or Duolingo 95 to 105.", "how_to_apply": "Apply for admission. All admitted international students are automatically considered for the MSU Non-resident Scholarship, with decisions by mid-February.", "deadlines": "Priority Feb 1 (decision by Mar 31). Final Apr 1. Early action Nov 1.", "fees_link": "https://admissions.msu.edu/cost-aid/scholarships/international", "sources": ["https://admissions.msu.edu/apply/international/admission-criteria", "https://admissions.msu.edu/apply/international/language-requirements", "https://admissions.msu.edu/cost-aid/scholarships/international"]}$q$::jsonb, admission_link = $q$https://admissions.msu.edu/cost-aid/scholarships/international$q$, admission_checked = '2026-11-13' where id = '49847e2b-40e7-4d9f-a63c-70fe10f7ca08' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the Rutgers Application or the Common App. Standardized tests are optional at New Brunswick. Letters of recommendation are not used. International students may use STARS but must mail official academic records after enrolling. Accepted records include WAEC.", "english": "A score is required if your secondary school was outside the US in a country where English is not the main language, whatever your citizenship. Minimum scores are on the Rutgers International Applicants page.", "how_to_apply": "Submit one application with the essay (3,800 characters or 250 to 650 words on the Common App) and the fee. Differences between STARS and official records can lead to admission being rescinded.", "application_fee": "$70, nonrefundable. Fee waivers exist for some groups.", "documents": "Application, essay, STARS record or official academic records (WAEC accepted), English proficiency score.", "fees_link": "https://admissions.rutgers.edu/node/135", "sources": ["https://admissions.rutgers.edu/node/135"]}$q$::jsonb, admission_link = $q$https://admissions.rutgers.edu/node/135$q$, admission_checked = '2026-11-13' where id = 'b936b258-b420-4ecb-b519-5abf15ede723' and country = 'United States';
update schools set admission_info = $q${"ug": "International students use the same application as everyone else (first-year or transfer). Send official transcripts and graduation credentials before enrolling.", "english": "Required if educated in a non-English-speaking country, unless English was the main language of instruction for all four years of secondary school. Minimums: Duolingo 115, IELTS 6.5, TOEFL iBT 80 (tests on or before Jan 20, 2026) or 4.5 (on or after Jan 21, 2026). No MyBest or superscores. Scores must be under two years old.", "how_to_apply": "Apply as a first-year or transfer student. Non-English transcripts need an official English translation with the original. Send English scores early because delivery takes 3 to 6 weeks. F-1 or J-1 students show funding for one year only after admission. Scholarships are listed at admissions.wisc.edu/international-scholarships.", "documents": "Curriculum transcripts and certificates (national certificates, IB, A-Levels), official English score report, official transcripts sent through official channels.", "fees_link": "https://admissions.wisc.edu/international/", "sources": ["https://admissions.wisc.edu/international/"]}$q$::jsonb, admission_link = $q$https://admissions.wisc.edu/international/$q$, admission_checked = '2026-11-13' where id = 'a8f826ba-93db-4842-acf3-44999a253762' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants self-report coursework and exam results and do not send official transcripts until they enroll. Show completion of secondary school that qualifies you for university in your home country.", "english": "Required for first-year applicants unless grades 10 to 12 were completed in an approved English-speaking country. Accepted: TOEFL, IELTS, Duolingo, ACT or SAT. Scores must be within two years of entry. The requirement cannot be waived. TOEFL code 1836.", "how_to_apply": "Apply directly to Illinois. The university does not use private recruiting agents. If you enroll, send official documents. If your country requires military service after school, finish it before applying.", "documents": "Self-reported coursework and exam results, English proficiency scores, official transcripts only if you enroll.", "fees_link": "https://admissions.illinois.edu/international-requirements/", "sources": ["https://admissions.illinois.edu/international-requirements/"]}$q$::jsonb, admission_link = $q$https://admissions.illinois.edu/international-requirements/$q$, admission_checked = '2026-11-13' where id = 'b67b40b3-665f-46be-9eea-9c0df55694d4' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply to a specific major. Give at least three consecutive years of courses and grades. Purdue expects four years of math and three years of lab science. Applicants from non-English-speaking countries do not need the world language requirement. Ghana applicants submit WAEC or NECO certificates. Some applicants may be asked to verify certificates through the WAEC Digital Certificate Platform.", "how_to_apply": "Apply to your major and send country-specific documents. Purdue says international undergraduates are generally not eligible for scholarships or financial aid, and its named scholarships are for domestic students only. No international scholarship is listed.", "documents": "Three consecutive years of courses and grades, proof of high school graduation before enrolling, WAEC or NECO certificate for Ghana, certified English translations for non-English records.", "fees_link": "https://admissions.purdue.edu/cost-financial-aid/scholarships/", "sources": ["https://www.admissions.purdue.edu/apply/international-students.php", "https://admissions.purdue.edu/cost-financial-aid/scholarships/"]}$q$::jsonb, admission_link = $q$https://www.admissions.purdue.edu/apply/international-students.php$q$, admission_checked = '2026-11-13' where id = '7103524e-dffd-4f8b-b192-45996d933337' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants who are finishing or have finished secondary school and have not attended college. Apply through the Common App. Send grade 9 to 12 transcripts.", "english": "Minimum TOEFL 80, IELTS 6.5, Duolingo 110, ACT English 18 or SAT EBRW 510 (freshmen only). Tests must be within two years. Exemptions include citizens of listed English-speaking countries, three years at a US high school with non-ESL English grades, or ELI Level 8 completion with a B or better.", "how_to_apply": "Apply through the Common App. You must meet both the application deadline and the I-20 deadline. Students on a visa cannot get a need-based fee waiver.", "deadlines": "Application: Spring Nov 15, Summer May 1, Fall Aug 1. I-20 documents: Spring Nov 15, Summer Apr 1, Fall Jun 1.", "application_fee": "$65, nonrefundable.", "documents": "Secondary school transcripts (grades 9 to 12, official English translation if needed; unofficial copies accepted for application, official copies if admitted), English proficiency proof.", "fees_link": "https://admissions.utah.edu/financial-aid-scholarships/scholarships/international-scholarships/", "sources": ["https://admissions.utah.edu/apply/international/international-freshman-admissions-undergraduate-costs/", "https://admissions.utah.edu/apply/international/english-proficiency/", "https://admissions.utah.edu/financial-aid-scholarships/scholarships/international-scholarships/"]}$q$::jsonb, admission_link = $q$https://admissions.utah.edu/financial-aid-scholarships/scholarships/international-scholarships/$q$, admission_checked = '2026-11-13' where id = '41c92858-f185-40bc-bb6c-d0ef15d5fbe9' and country = 'United States';
update schools set admission_info = $q${"ug": "Direct admission through the Common App. Conditional admission through the English Language Institute (Academic Transitions) is open for most majors except nursing. Lerner College and Engineering applicants are generally expected to have pre-calculus.", "english": "Direct admission: TOEFL iBT 79 (4 on the new scale), IELTS 6.5, Duolingo 110, PTE 53, Cambridge B2 First 171. Academic Transitions: TOEFL 65 to 78, IELTS 5.5 to 6.0, Duolingo 95 to 109. Alternatives include SAT English 550, ACT English 24 or IB English 6. School code 5811.", "how_to_apply": "Apply with the Common App (direct) or the UD Online Application (conditional). Decisions are rolling. International students pay the non-resident rate.", "deadlines": "Honors Nov 1. Nursing and Music priority Dec 1. Direct freshman priority Jan 15. Conditional freshman Jun 1.", "application_fee": "$75.", "documents": "Official transcripts and exam results (electronic accepted for review, sealed official copies before enrollment), English test scores, IERF credential evaluation for those with international college study (required for Lerner and Engineering).", "fees_link": "https://www.udel.edu/apply/undergraduate-admissions/international-students/international-admissions-requirements/", "sources": ["https://www.udel.edu/apply/undergraduate-admissions/international-students/international-admissions-requirements/"]}$q$::jsonb, admission_link = $q$https://www.udel.edu/apply/undergraduate-admissions/international-students/international-admissions-requirements/$q$, admission_checked = '2026-11-13' where id = '47d60e3c-2296-438d-8597-0c408fb82169' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply as a first-year, transfer or adult student. Use your full legal name exactly as on your passport. An optional InitialView interview is available.", "english": "Competitive scores for the Pittsburgh campus: TOEFL 100+ (5.0+ new scale), IELTS 7.0+, Duolingo 125+. TOEFL 90 to 99 with a strong record gets strong consideration. TOEFL 80 to 89, IELTS 6.5 or Duolingo 115 to 120 are mostly considered for the Bradford, Greensburg or Johnstown campuses. TOEFL MyBest and TOEFL Essentials are not accepted. A waiver is possible with SAT EBRW 660 or ACT English 27.", "how_to_apply": "Apply online with test scores and transcripts. Decisions usually take 6 to 8 weeks after all items arrive. International first-year scholarship awards need no separate application but need an essay or personal statement.", "deadlines": "Scholarship review: complete application by Feb 1 (fall term). Decisions weekly, notices by Apr 1.", "documents": "Transcripts, test scores, English proficiency scores, essay or personal statement (for scholarship review).", "fees_link": "https://admissions.pitt.edu/?p=674", "sources": ["https://admissions.pitt.edu/?p=674", "https://admissions.pitt.edu/?p=732"]}$q$::jsonb, admission_link = $q$https://admissions.pitt.edu/?p=674$q$, admission_checked = '2026-11-13' where id = 'e8575558-9b85-4560-85a9-fa591a521746' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply as a first-year through the Common App. The 2026 freshman middle 50 percent was ACT 32 to 35 and SAT 1420 to 1520.", "english": "The international transfer page lists TOEFL iBT 80 and IELTS 6.0 (code 5812 for TOEFL). The freshman English page was not confirmed. Check admissions.ufl.edu for first-year scores.", "how_to_apply": "Meet the deadlines for admissions scholarship consideration. UF estimates 2026 to 27 cost for F-1 and J-1 students at $59,394 including $31,869 tuition and $3,185 health insurance.", "deadlines": "Early Decision Oct 15. Early Action Nov 1. Regular Decision Jan 15 (2026 to 27 freshman).", "fees_link": "https://www.admissions.ufl.edu/cost-and-aid/scholarships", "sources": ["https://admissions.ufl.edu/international-admissions-guide", "https://admissions.ufl.edu/apply/transfer/international", "https://www.admissions.ufl.edu/cost-and-aid/scholarships"]}$q$::jsonb, admission_link = $q$https://www.admissions.ufl.edu/cost-and-aid/scholarships$q$, admission_checked = '2026-11-13' where id = '7a6f5fef-b984-4bf0-9f7b-5f628f249c20' and country = 'United States';
update schools set admission_info = $q${"ug": "Submit final English-translated transcripts from each school. Most first-year students show English through SAT or ACT scores required by the Board of Regents. Do not self-report grades.", "english": "First-year: mostly SAT or ACT. IELTS or TOEFL also accepted. Admitted international averages (2019 to 2023): SAT EBRW 650, ACT English 30, IELTS 7.5, TOEFL 102. Transfer minimums: SAT EBRW 480, ACT English 17, IELTS 6.5, TOEFL iBT 80. Codes: TOEFL and SAT 5813, ACT 0872. Scores must be under 5 years old.", "how_to_apply": "Apply as first-year if you never attended college, or transfer if you did. Green Card holders apply as domestic. The page does not list scholarships for international students.", "documents": "Final English-translated transcripts, English proficiency documentation, course by course evaluation for transfer applicants from non-accredited non-US schools.", "fees_link": "https://admissions.uga.edu/apply/other-applicants/international-students/", "sources": ["https://admissions.uga.edu/apply/other-applicants/international-students/"]}$q$::jsonb, admission_link = $q$https://admissions.uga.edu/apply/other-applicants/international-students/$q$, admission_checked = '2026-11-13' where id = 'b67bf860-f4fe-4788-9d57-3d91092d8aaa' and country = 'United States';
update schools set admission_info = $q${"ug": "Complete the Common App. Requirements vary by country, mainly the transcript type. Do not send extra documents unless asked. SAT or ACT can be self-reported (U-M codes ACT 2062, SAT 1839).", "how_to_apply": "Apply through the Common App. Michigan says international students on temporary visas are not eligible for financial aid and must pay the full cost. Few scholarships are available.", "deadlines": "Early Action Nov 1. Fall Feb 1. Winter Oct 1. Spring Feb 1. Summer Feb 1. Deadlines vary by school or program.", "documents": "Common App and country-specific transcripts.", "fees_link": "https://prod.lsa.umich.edu/scholarships/prospective-students/international-students.html", "sources": ["https://admissions.umich.edu/apply/international-applicants/requirements-deadlines", "https://prod.lsa.umich.edu/scholarships/prospective-students/international-students.html"]}$q$::jsonb, admission_link = $q$https://prod.lsa.umich.edu/scholarships/prospective-students/international-students.html$q$, admission_checked = '2026-11-13' where id = 'c683c6e1-807b-4251-85cc-139d3188b812' and country = 'United States';
update schools set admission_info = $q${"ug": "Equivalent of a 3.0 GPA on a 4.0 scale. Four years of English, three of science (two lab), three of math and two of social studies. SAT or ACT is optional (SAT 1200 or ACT 25 meets the GPA rule).", "english": "Undergraduate: TOEFL iBT 71 (4.0 new scale), IELTS 6.0 (no subscore under 5.5), Duolingo 105, PTE 48, SAT EBRW 460, ACT English 19. Exempt if you graduated from a US high school or are a native English speaker in a country where English is the main official language. MyBest and IELTS One Skill Retake are not accepted.", "how_to_apply": "Apply with English test results, transcripts, a bank statement or sponsor letter and a passport copy. Scans are fine for review, official documents are needed if admitted. Iowa State lists International Student Excellence Award and International Merit Scholarships.", "documents": "English test results, transcripts from all schools, bank statement or sponsor letter showing $52,000 (most majors) or $54,300 (Design and Animal Enterprise and Innovation), passport copy.", "fees_link": "https://iastate.edu/admission-and-aid/admissions/international-admissions/international-first-year-requirements", "sources": ["https://iastate.edu/admission-and-aid/admissions/international-admissions/international-first-year-requirements", "https://www.iastate.edu/admission-and-aid/admissions/international-admissions/english-proficiency-requirement"]}$q$::jsonb, admission_link = $q$https://iastate.edu/admission-and-aid/admissions/international-admissions/international-first-year-requirements$q$, admission_checked = '2026-11-13' where id = 'f3cd6b0e-2422-47ea-9844-d7215cf620f3' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen send an official high school transcript and official ACT or SAT scores (ACT code 1990, SAT code 1201). Credentials from outside the US need an evaluation from Educational Perspectives.", "english": "Proof of English proficiency is required. Specific scores are not listed on the application form.", "how_to_apply": "Apply online at emich.edu/apply or send the form by mail. Freshman applicants are automatically considered for academic scholarships. No international-specific scholarship is named.", "deadlines": "Priority: Fall July 1. Winter Nov 1. Summer Mar 1.", "application_fee": "$35, nonrefundable, paid by check or money order.", "documents": "Official high school transcript, ACT or SAT scores, credential evaluation (Educational Perspectives) for non-US college work, financial documents for most international applicants, copy of visa or I-94 if in the US.", "fees_link": "https://www.emich.edu:443/admissions/documents/emu-undergraduate-admission-application-information.pdf", "sources": ["https://www.emich.edu:443/admissions/documents/emu-undergraduate-admission-application-information.pdf"]}$q$::jsonb, admission_link = $q$https://www.emich.edu:443/admissions/documents/emu-undergraduate-admission-application-information.pdf$q$, admission_checked = '2026-11-13' where id = '7f4c2257-00ee-47df-bbc2-3ed25328e112' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen apply with the UK International Application or the Common App and send official English transcripts. SAT or ACT is optional except for engineering programs (codes ACT 1554, SAT 1837).", "pg": "Apply through the UK Graduate School at gradschool.uky.edu/apply. Requirements are set by program.", "english": "TOEFL iBT 71 (4 overall and each subscore on the new scale), TOEFL Essentials 7.5, IELTS 6.0, or Duolingo 105. Some countries are exempt.", "how_to_apply": "Apply for admission first to be considered for scholarships. International undergraduates are considered for academic scholarships. Freshman priority deadline is Dec 1.", "deadlines": "Freshman: Fall Dec 1, Spring Oct 15. Transfer: Fall May 15, Spring Oct 15.", "application_fee": "$60, nonrefundable.", "documents": "Application, official transcripts in English, English test scores.", "fees_link": "https://studentsuccess.uky.edu/financial-aid-and-scholarships/international-student-undergraduate-scholarships", "sources": ["https://international.uky.edu/apply/admission-requirements", "https://studentsuccess.uky.edu/financial-aid-and-scholarships/international-student-undergraduate-scholarships"]}$q$::jsonb, admission_link = $q$https://studentsuccess.uky.edu/financial-aid-and-scholarships/international-student-undergraduate-scholarships$q$, admission_checked = '2026-11-13' where id = '1f9456bc-40bd-43fb-a3cf-641ab26db33f' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply through the Common App only. Temple is test optional. Some Boyer, Tyler and Theater, Film and Media Arts majors need an audition, interview or portfolio.", "english": "University admission: TOEFL iBT 79 (4.0 new scale), IELTS 6.0, Duolingo 110, PTE 53, Cambridge C1 180, SAT EBRW 550. Bridge Program for slightly lower scores (TOEFL 74 to 78, IELTS 5.5, Duolingo 100 to 105). You are exempt if English is your native language or you studied three or more years in English. TOEFL code 2906.", "how_to_apply": "Apply through the Common App. Admitted students decide within two weeks of the offer. Bridge admits still get any merit scholarships they earn.", "deadlines": "Early Action Nov 1. Regular Decision Feb 1. Spring Dec 15. Deposit May 1.", "application_fee": "$55 (waiver possible).", "documents": "Official secondary transcripts with English translations (grades 9 to 11 plus current progress), optional recommendation letters, proof of graduation after paying the deposit.", "fees_link": "https://admissions.temple.edu/apply/international-students/scholarships", "sources": ["https://admissions.temple.edu/apply/international-students/first-year-international-students", "https://admissions.temple.edu/apply/international-students/scholarships"]}$q$::jsonb, admission_link = $q$https://admissions.temple.edu/apply/international-students/scholarships$q$, admission_checked = '2026-11-13' where id = '4d93ea59-35f2-4f87-ab9c-11d4550b589f' and country = 'United States';
update schools set admission_info = $q${"ug": "High school GPA of 2.7 or higher (last three years) or GED 660. College transcripts need a 2.7 GPA. F-1 bachelor's students study on the Logan main campus and take most classes in person. SAT or ACT is optional.", "english": "Send TOEFL and SAT to code 4857, ACT to 4276, Duolingo through its portal, IELTS, MET and Cambridge as a student copy upload. Minimum scores are on the USU English page. Submit scores at least one month before the deadline.", "how_to_apply": "Submit the undergraduate application, pay the fee, upload documents, send transcripts and English scores, then pay a $200 enrollment deposit after admission. Fee waivers are not available.", "deadlines": "Priority: Fall Mar 1 (deposit Apr 1). Spring Oct 1 (deposit Nov 1).", "application_fee": "$50, nonrefundable.", "documents": "Transcripts (certified English translations), English scores, supplemental items. Degree certificate if you hold a bachelor's degree.", "fees_link": "https://www.usu.edu/admissions/international/undergraduate-costs", "sources": ["https://www.usu.edu/admissions/international/", "https://www.usu.edu/admissions/international/undergraduate-costs"]}$q$::jsonb, admission_link = $q$https://www.usu.edu/admissions/international/undergraduate-costs$q$, admission_checked = '2026-11-13' where id = '3a7cd6d2-7d5c-4175-9bad-70f554cc6555' and country = 'United States';
update schools set admission_info = $q${"ug": "Holistic review of marks, test scores, essay and recommendations. UB expects the equivalent of a 3.0 (B or 83 percent). Submit transcripts or state exam results. Some majors need extra items such as auditions, portfolios or pre-calculus.", "english": "Minimum scores are on the UB English proficiency page, not confirmed here.", "how_to_apply": "Submit one application: SUNY, Common App or Coalition. All admitted international students are automatically considered for the Flagship Scholarship.", "deadlines": "Fall: Early Action Nov 1, Honors priority Dec 15, Regular Feb 1 (open until capacity). Spring: Oct 1 recommended.", "application_fee": "$50, nonrefundable.", "documents": "Transcripts or state exam results, English translations if needed.", "fees_link": "https://www.buffalo.edu/internationaladmissions/affordable-costs-and-funding-opportunities/scholarships-funding.html", "sources": ["https://www.buffalo.edu/admissions/apply/international/first-year.html", "https://www.buffalo.edu/internationaladmissions/affordable-costs-and-funding-opportunities/scholarships-funding.html"]}$q$::jsonb, admission_link = $q$https://www.buffalo.edu/internationaladmissions/affordable-costs-and-funding-opportunities/scholarships-funding.html$q$, admission_checked = '2026-11-13' where id = '4d481608-d6f6-470a-80df-bc0b09816ce0' and country = 'United States';
update schools set admission_info = $q${"ug": "Complete a college-preparatory secondary program that qualifies you for university in your home country. UC looks for four years of math, three to four years of science and three to four years of language, history, social science or electives. A recommendation letter is optional.", "english": "College of Arts and Sciences minimums: SAT EBRW 480, ACT 19, IELTS 6.5 (5.5 per subscore), TOEFL iBT 79 (4.0 new), Duolingo 100, Cambridge 176, PTE 53, ELS 112. Minimums vary by college. Scores must be under two years old. Four exemption routes exist.", "how_to_apply": "Apply through the Common App. Admission is rolling. UC does not offer full-tuition or need-based scholarships to international undergraduates.", "deadlines": "Early Action Nov 1 (needed for Honors). Rolling: Summer and Fall Mar 1, Spring Nov 1.", "application_fee": "$100, nonrefundable.", "documents": "Common App, official transcripts (certified English translation), SAT or ACT optional, optional recommendation letter.", "fees_link": "https://admissions.uc.edu/information/international/finance/scholarship.html", "sources": ["https://admissions.uc.edu/information/international/requirements/freshman", "https://admissions.uc.edu/information/international/finance/scholarship.html"]}$q$::jsonb, admission_link = $q$https://admissions.uc.edu/information/international/finance/scholarship.html$q$, admission_checked = '2026-11-13' where id = '704111c2-02cc-48a5-9ca1-9ab1c6b8c4cb' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply through the Common App (Summer or Fall) or Spring App. At least one SAT or ACT score is required (codes SAT 6882, ACT 4240). Send at least one essay plus short answers and records of grades 9 to 12. Optional resume and two recommendation letters.", "english": "Submit TOEFL, IELTS or Duolingo if it applies to you. Minimum scores are on the UT International Students page, not confirmed here.", "how_to_apply": "Apply online and pay the fee. Fee waivers are not available to international students.", "deadlines": "Summer and Fall: Early Action Oct 15, Regular Dec 1. Spring: Sep 1.", "application_fee": "$90, nonrefundable.", "documents": "Application, essays, official SAT or ACT, transcripts (grades 9 to 12), English test if applicable, extra items for some majors.", "fees_link": "https://admissions.utexas.edu/apply/international-students/", "sources": ["https://admissions.utexas.edu/apply/international-students/"]}$q$::jsonb, admission_link = $q$https://admissions.utexas.edu/apply/international-students/$q$, admission_checked = '2026-11-13' where id = '67557b4e-b22b-4d28-8479-0f7fdd5ca37b' and country = 'United States';
update schools set admission_info = $q${"ug": "Finish secondary school at home. Minimum GPA 2.5 on a 4.0 scale. SAT or ACT not required. Some majors are more selective.", "pg": "Graduate programs set their own English and admission rules. Apply with passport page, English results, transcripts, diploma and any GRE or GMAT the program requires.", "english": "TOEFL iBT 71, IELTS 6.0, Duolingo 100, PTE 48, SAT EBRW 510, ACT English 21, ESL Center Level 8 (3.75 GPA) or ELS 112. Lower scores may get conditional admission with ESL classes. TOEFL code 1367.", "how_to_apply": "Apply online and upload scans. Financial documents are required only after acceptance. Bring final official transcripts and diploma in the first semester.", "deadlines": "Fall Jun 1. Spring Oct 1. Late applications accepted.", "application_fee": "$70, nonrefundable.", "documents": "Passport page, English scores, diploma or certificate and transcripts (certified English translation plus original), major-specific items, financial documents after acceptance.", "fees_link": "https://www.kent.edu/node/952858", "sources": ["https://www.kent.edu/admissions/international-first-year-student-requirements", "https://www.kent.edu/admissions/international-graduate-student-requirements", "https://www.kent.edu/node/952858"]}$q$::jsonb, admission_link = $q$https://www.kent.edu/node/952858$q$, admission_checked = '2026-11-13' where id = '4de15eab-975b-4c12-acf8-cfedb2790a07' and country = 'United States';
update schools set admission_info = $q${"how_to_apply": "After admission and enrollment, international students show funds for one year of costs (tuition, fees, books, insurance, living). UMD says that as a public university it cannot offer financial assistance to international students, so no international scholarship is listed.", "documents": "Proof of funds for one year, submitted only after you receive an offer and confirm enrollment. Medical insurance is required.", "fees_link": "https://admissions.umd.edu/apply/financial-certification", "sources": ["https://admissions.umd.edu/apply/financial-certification"]}$q$::jsonb, admission_link = $q$https://admissions.umd.edu/apply/financial-certification$q$, admission_checked = '2026-11-13' where id = '58e91bda-c0a1-467b-9291-e9db04f0e07e' and country = 'United States';
update schools set admission_info = $q${"ug": "Conditional admission is available if you meet academic requirements but not English requirements. You start in the English Language Institute or the Pathway to UA program before full coursework.", "english": "Conditional admission does not need an English score at application. Scores are on the UA English Language Proficiency Policy page.", "how_to_apply": "For scholarships, UA says values and names are the same for international and out-of-state students. Automatic awards need submitted ACT or SAT scores. Competitive scholarships can be considered without scores.", "deadlines": "Spring 2027: application and scores by Nov 2. Summer or Fall 2027: Dec 4. Conditional admission: Fall session 1 May 1, Spring session 1 Oct 1.", "documents": "Application and official ACT or SAT scores for automatic scholarships (no superscores).", "fees_link": "https://afford.ua.edu/scholarships/international/", "sources": ["https://admissions.ua.edu/international/conditional", "https://afford.ua.edu/scholarships/international/"]}$q$::jsonb, admission_link = $q$https://afford.ua.edu/scholarships/international/$q$, admission_checked = '2026-11-13' where id = 'b2df4a3e-63fa-4029-ab72-36d385083ebf' and country = 'United States';
update schools set admission_info = $q${"ug": "Ghana applicants: WASSCE grade C5 for admission, B3 for scholarship consideration. Converted GPA 2.0 for admission and 3.0 for scholarship. University transfers: 50 percent average (70 percent for scholarship), or at least upper second class for scholarship.", "english": "For Ghana applicants, citizenship counts as proof of English. No English test score is needed.", "how_to_apply": "Students still in school may apply with unofficial school transcripts, then send final WASSCE results. Transfer applicants send official transcripts from every university. Meeting scholarship minimums does not guarantee an award.", "documents": "WASSCE results (secondary applicants) or official transcripts from each university (transfer applicants).", "fees_link": "https://financialaid.wvu.edu/home/scholarships/international", "sources": ["https://www.wvu.edu/admissions/undergraduate/how-to-apply/international-students/admission-requirements-for-international-students/ghana/", "https://financialaid.wvu.edu/home/scholarships/international"]}$q$::jsonb, admission_link = $q$https://www.wvu.edu/admissions/undergraduate/how-to-apply/international-students/admission-requirements-for-international-students/ghana/$q$, admission_checked = '2026-11-13' where id = 'b72b322f-b56c-472b-a9e3-5eee48a330a4' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply as first-year if you finished secondary school without college, or as transfer if you took college courses. You need a secondary school completion certificate that gives access to university in your country. Report international coursework as it appears on records. Do not convert grades or use an evaluation service.", "english": "You may need to show English proficiency depending on the language of instruction at your school. Scores are on the International Exam and Visa Requirements page.", "how_to_apply": "Apply through the UC application as first-year or transfer.", "documents": "International records reported as they appear on the originals.", "fees_link": "https://aggiehero.ucdavis.edu/admissions/undergraduate/international", "sources": ["https://aggiehero.ucdavis.edu/admissions/undergraduate/international"]}$q$::jsonb, admission_link = $q$https://aggiehero.ucdavis.edu/admissions/undergraduate/international$q$, admission_checked = '2026-11-13' where id = '00b20ba2-a7e9-4bc5-8df1-e5b0d2ac4807' and country = 'United States';
update schools set admission_info = $q${"ug": "Admission is selective and needs above-average secondary grades. For Cambridge exams, usually at least 6 passes at grade C or higher. IB: generally an average of 5. Some programs are stricter. SAT or ACT, essays and recommendations are optional.", "english": "TOEFL iBT 72 (writing 17) or 4 (new scale), IELTS 6.0 (no subscore under 5.5), Duolingo 110, PTE 48, Cambridge 169, SAT 1060 (EBRW 540), ACT 21. Exams must be within one year. Exempt if from a listed country (including Ghana and Nigeria) or if you did three years of higher secondary school in English. OPIE intensive English is available.", "how_to_apply": "Complete the Athens campus application (Common App or OHIO application) and pay the fee. International students starting in fall are automatically considered for merit scholarships. Priority deadline Nov 15, 2026, notices from December.", "deadlines": "Priority Nov 15, 2026 (merit scholarship notices begin in December). Test scores for scholarships by Jan 15.", "application_fee": "$75.", "documents": "Academic records from every secondary school (certified English translation), proof of English proficiency unless exempt. I-20 funds are reduced by scholarships you receive.", "fees_link": "https://www.ohio.edu/admissions/admitted/international", "sources": ["https://www.ohio.edu/admissions/international/apply", "https://www.ohio.edu/admissions/admitted/international"]}$q$::jsonb, admission_link = $q$https://www.ohio.edu/admissions/admitted/international$q$, admission_checked = '2026-11-13' where id = '4cdef49d-7c4c-42a6-9fa9-578d9b395172' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshman: a recognized secondary completion certificate, about a 3.0 GPA on the US scale, and age 17 before the first day of classes. Non-Oklahoma residents applying to engineering or computer science need a 3.0.", "english": "TOEFL iBT 79 (about 20 per section), IELTS 6.5, Duolingo 100, or PTE 53. Or secondary school or 24 college credits in a native English country, or OU CESL completion. Scores older than two years are not accepted.", "how_to_apply": "Apply online and pay the fee. Financial documentation (dated within 90 days) is needed after admission for the I-20. No international scholarships are listed on the admissions page.", "deadlines": "Applicants outside the US, freshman: Summer Feb 1, Fall Feb 1 (credentials Apr 15), Spring Nov 1 (credentials Nov 15).", "application_fee": "$90, nonrefundable.", "documents": "Official transcripts from every school (English translation), passport page and visa copy, financial documents after admission, optional recommendation letters.", "fees_link": "https://www.ou.edu/globalengagement/international-student-scholarships", "sources": ["https://ou.edu/admissions/apply/international/undergraduate-admission", "https://www.ou.edu/globalengagement/international-student-scholarships"]}$q$::jsonb, admission_link = $q$https://www.ou.edu/globalengagement/international-student-scholarships$q$, admission_checked = '2026-11-13' where id = '0557f6a0-c3f4-4ed0-bddc-f39775bb2464' and country = 'United States';
update schools set admission_info = $q${"ug": "Show English skills and send transcripts or mark sheets from all secondary and post-secondary schools, with official grading scales. Unofficial transcripts are accepted for the decision; official ones are due by the end of the first semester.", "pg": "Complete the graduate application and follow your department's rules. Programs may ask for a narrative statement, test scores and reference letters. Graduate applicants from Ghana, Kenya or Nigeria are told to contact a named admissions officer, Dr. Randall Janes (randall.a.janes@wmich.edu).", "english": "Undergraduate: TOEFL iBT 71, IELTS 6.0, Duolingo 100, PTE 48. Graduate: TOEFL iBT 80, IELTS 6.5, Duolingo 105, PTE 54. Some programs need higher scores. Scores must be less than two years old.", "how_to_apply": "Apply online through the WMU international application portal. If you do not meet the English score, you can start in the Center for English Language and Culture. Many programs admit on a rolling basis.", "deadlines": "Undergraduate: Fall June 1, Spring Sept 1, Summer One Feb 1. Graduate: Fall April 1, Spring July 1, Summer One Dec 1; programs may set earlier dates. For the graduate merit scholarship, apply by Feb 15.", "application_fee": "$100, not refundable, paid online by card.", "documents": "Transcripts or mark sheets, diplomas and exam results, official grading scales, English translations, and a passport ID page copy. Credential evaluations from approved services are also accepted.", "fees_link": "https://wmich.edu/international/financial-aid", "sources": ["https://wmich.edu/internationaladmissions/apply/undergraduate", "https://wmich.edu/internationaladmissions/apply/graduate", "https://wmich.edu/internationaladmissions/proficiency", "https://wmich.edu/international/financial-aid"]}$q$::jsonb, admission_link = $q$https://wmich.edu/internationaladmissions/apply/graduate$q$, admission_checked = '2026-11-13' where id = 'b8222862-421a-4a40-9f2b-80b57197cab2' and country = 'United States';
update schools set admission_info = $q${"ug": "Finish the undergraduate application, pay the fee, and send all transcripts. Transcripts must be translated into English by an accredited evaluation agency, with course descriptions for credit transfer.", "pg": "Equivalent of a US four-year bachelor's degree. Master's applicants need a minimum GPA of 2.75 and doctoral applicants 3.0. Programs may set higher standards.", "english": "Applicants must meet Wayne State's English rules; the pages checked do not list minimum scores. English tests must be no more than two years old. Applicants who miss the English level may get provisional graduate admission through the English Language Institute.", "how_to_apply": "Apply online with the undergraduate application. Graduate applicants send a course-by-course credential evaluation (WES, ECE or SpanTran) straight from the evaluator to Graduate Admissions.", "deadlines": "Undergraduate: Fall Aug 1, Winter Dec 1, Spring/Summer April 1. Graduate credential evaluation due dates: Fall July 31, Winter Nov 30, Spring/Summer April 30; program deadlines can be earlier.", "application_fee": "$25 for undergraduate applicants. Graduate fee not stated on the page checked.", "documents": "Copies of all transcripts, English translations, course descriptions, a signed statement of financial support with a bank statement dated within six months, proof of citizenship, and a visa copy if you hold non-immigrant status. Graduate: official credential evaluation, then a bank statement and Affidavit of Support after acceptance.", "fees_link": "https://livingdetroit.wayne.edu/admissions/international/deadlines", "sources": ["https://livingdetroit.wayne.edu/admissions/international/deadlines", "https://gradschool.wayne.edu/admissions/international", "https://next.wayne.edu/scholarships/international"]}$q$::jsonb, admission_link = $q$https://livingdetroit.wayne.edu/admissions/international/deadlines$q$, admission_checked = '2026-11-13' where id = 'c1601f67-b989-430d-a0d1-f8cdfd1a482d' and country = 'United States';
update schools set admission_info = $q${"ug": "Finish secondary school and be eligible for university in your home country. Take college-prep courses in English, math, physical science and social science. Engineering applicants need secondary physics and chemistry.", "pg": "Not stated on the first-year page. UConn regional campuses are mainly undergraduate.", "english": "Needed if English is not your first language: TOEFL 79, IELTS 6.5, Duolingo 110, PTE 60, LanguageCert 70. Waivers exist, for example SAT Reading and Writing 510 or higher, or a degree taught in English.", "how_to_apply": "Apply through the Common App or Coalition App to UConn and choose the regional campus. Regional campuses decide on a rolling basis.", "deadlines": "Fall regional campuses: May 1. Spring: Oct 1. Deposit due May 1.", "application_fee": "$80, not refundable.", "documents": "Common or Coalition application, essay of 250 to 650 words, official secondary transcripts, transcripts from any college attended, certified English translations. Two recommendation letters are optional.", "fees_link": "https://admissions.uconn.edu/apply/international/first-year/", "sources": ["https://admissions.uconn.edu/apply/international/first-year/", "https://admissions.uconn.edu/cost-aid/scholarship/"]}$q$::jsonb, admission_link = $q$https://admissions.uconn.edu/apply/international/first-year/$q$, admission_checked = '2026-11-13' where id = 'df40cd48-a636-4cff-b465-6164b2f016aa' and country = 'United States';
update schools set admission_info = $q${"ug": "Finish secondary school and be eligible for university in your home country. Take college-prep courses in English, math, physical science and social science. Engineering applicants need secondary physics and chemistry.", "pg": "Not covered on the pages checked.", "english": "Needed if English is not your first language: TOEFL 79, IELTS 6.5, Duolingo 110, PTE 60, LanguageCert 70. Waivers exist, for example SAT Reading and Writing 510 or higher, or a degree taught in English. UCAELI, UConn's English institute, can also meet the rule.", "how_to_apply": "Apply through the Common App or Coalition App. All applicants are considered for merit scholarships and Honors, with or without test scores.", "deadlines": "Fall: Nov 1 early decision, Dec 1 priority for merit and honors, Jan 15 for Storrs. Spring: Oct 1. Deposit due May 1.", "application_fee": "$80, not refundable.", "documents": "Common or Coalition application, essay of 250 to 650 words, official secondary transcripts, transcripts from any college attended, certified English translations. SAT or ACT is optional. Two recommendation letters are optional.", "fees_link": "https://admissions.uconn.edu/apply/international/first-year/", "sources": ["https://admissions.uconn.edu/apply/international/first-year/", "https://admissions.uconn.edu/cost-aid/scholarship/"]}$q$::jsonb, admission_link = $q$https://admissions.uconn.edu/apply/international/first-year/$q$, admission_checked = '2026-11-13' where id = 'e597c805-0e3f-4e30-8a49-52015e5bb249' and country = 'United States';
update schools set admission_info = $q${"ug": "Finish secondary school and be eligible for university in your home country. Take college-prep courses in English, math, physical science and social science.", "pg": "Not stated on the first-year page. UConn regional campuses are mainly undergraduate.", "english": "Needed if English is not your first language: TOEFL 79, IELTS 6.5, Duolingo 110, PTE 60, LanguageCert 70. Waivers exist for some applicants.", "how_to_apply": "Apply through the Common App or Coalition App to UConn and choose the regional campus. Regional campuses decide on a rolling basis.", "deadlines": "Fall regional campuses: May 1. Spring: Oct 1. Deposit due May 1.", "application_fee": "$80, not refundable.", "documents": "Common or Coalition application, essay of 250 to 650 words, official secondary transcripts, transcripts from any college attended, certified English translations.", "fees_link": "https://admissions.uconn.edu/apply/international/first-year/", "sources": ["https://admissions.uconn.edu/apply/international/first-year/"]}$q$::jsonb, admission_link = $q$https://admissions.uconn.edu/apply/international/first-year/$q$, admission_checked = '2026-11-13' where id = 'f15a741e-37c1-4653-a3a7-c38cfe604151' and country = 'United States';
