update schools set admission_info = $q${"ug": "Finish secondary school and be eligible for university in your home country. Take college-prep courses in English, math, physical science and social science.", "pg": "Not stated on the first-year page. UConn regional campuses are mainly undergraduate.", "english": "Needed if English is not your first language: TOEFL 79, IELTS 6.5, Duolingo 110, PTE 60, LanguageCert 70. Waivers exist for some applicants.", "how_to_apply": "Apply through the Common App or Coalition App to UConn and choose the regional campus. Regional campuses decide on a rolling basis.", "deadlines": "Fall regional campuses: May 1. Spring: Oct 1. Deposit due May 1.", "application_fee": "$80, not refundable.", "documents": "Common or Coalition application, essay of 250 to 650 words, official secondary transcripts, transcripts from any college attended, certified English translations.", "fees_link": "https://admissions.uconn.edu/apply/international/first-year/", "sources": ["https://admissions.uconn.edu/apply/international/first-year/"]}$q$::jsonb, admission_link = $q$https://admissions.uconn.edu/apply/international/first-year/$q$, admission_checked = '2026-11-13' where id = 'f6ebc7fa-2760-49fd-86a1-0808a2dbe967' and country = 'United States';
update schools set admission_info = $q${"ug": "Assured admission with a high school GPA of 3.0 or higher on a 4.0 scale. Others are reviewed as a whole, and some colleges add their own rules.", "pg": "Upload transcripts for all bachelor's and graduate study. External credential evaluation is not required. Applicants from India need a four-year bachelor's, or a master's in addition to a three-year bachelor's.", "english": "Undergraduate: TOEFL iBT 3.5 (new scale), IELTS 5.5, PTE 46, iTEP 3.5, Duolingo 95. Graduate: TOEFL iBT 79 (4.0 new scale), IELTS 6.5, Duolingo 115, PTE 53. Conditional admission is possible for some applicants who need more English.", "how_to_apply": "Undergraduate: apply through the OSU application or the Common App. Graduate: apply online; the Graduate College handles international applications.", "deadlines": "Graduate: Fall May 1, Spring Oct 1, Summer Feb 1; programs may be earlier. Undergraduate scholarship priority date is Feb 1. The undergraduate page lists no application deadline.", "application_fee": "$90 undergraduate, $75 graduate. Graduate fee waivers are generally not given to international students.", "documents": "Passport ID page, English test score, high school and college transcripts in the original language with English translation, and a financial guarantee form with a bank letter. Third-party credential evaluations are not accepted for undergraduates.", "fees_link": "https://go.okstate.edu/admissions/international/freshman", "sources": ["https://go.okstate.edu/admissions/international/freshman", "https://gradcollege.okstate.edu/prospective-students/international-students/international-students-admissions-requirements", "https://go.okstate.edu/scholarships-financial-aid/types-of-aid/scholarships-and-grants/international-scholarships"]}$q$::jsonb, admission_link = $q$https://go.okstate.edu/admissions/international/freshman$q$, admission_checked = '2026-11-13' where id = '8f6dc54a-faa7-4a9b-99bf-afabedd9e9a7' and country = 'United States';
update schools set admission_info = $q${"ug": "Send your high school transcripts and an SAT, ACT or CLT score. USF encourages submitting more than one test.", "pg": "Foreign bachelor's or graduate degree equal to a US one, with a minimum GPA of 3.00. Programs may ask for test scores, recommendation letters or a statement of purpose.", "english": "Undergraduate: SAT Reading and Writing 490, or ACT English 17 and Reading 19, or CLT 38. TOEFL and IELTS are not accepted for freshmen. Graduate: TOEFL iBT 79, IELTS 6.5, PTE 53, Duolingo 105, or GRE Verbal 153.", "how_to_apply": "Apply on the USF online application or the Common App. Send documents from your school's official email to the USF international transcripts address.", "deadlines": "Freshman: take the SAT, ACT or CLT before December for Summer or Fall. Graduate deadlines depend on the department.", "application_fee": "$30 for undergraduates, paid by international wire through Flywire. Graduate fee not stated.", "documents": "Official transcripts (final ones after admission), certified English translations, test scores sent directly from the test agency. Graduate: official transcripts, credential evaluation if asked, GRE or GMAT if the program needs it.", "fees_link": "https://www.usf.edu/admissions/international/admission-information/undergraduate/freshmen-how-to-apply.aspx", "sources": ["https://www.usf.edu/admissions/international/admission-information/undergraduate/freshmen-how-to-apply.aspx", "https://testsite.usf.edu/admissions/archive/international/graduate/requirements-and-deadlines.aspx"]}$q$::jsonb, admission_link = $q$https://www.usf.edu/admissions/international/admission-information/undergraduate/freshmen-how-to-apply.aspx$q$, admission_checked = '2026-11-13' where id = '76272d0b-7173-4f84-bf52-a5598fa6078e' and country = 'United States';
update schools set admission_info = $q${"ug": "Assured admission is based on class rank and test scores. Top 10 percent has no minimum; first quarter needs ACT 24 or SAT 1180. Others get a full review. SAT and ACT are optional.", "pg": "Bachelor's degree from an accredited US school or an equal degree from a foreign school recognized by its government. Good academic standing is required.", "english": "Undergraduate: proof of English required; the page checked gives no scores. Graduate: TOEFL iBT 79, IELTS 6.5, Duolingo 100, PTE 60. Scores are valid for two years.", "how_to_apply": "Undergraduate: use the Common App, ApplyTexas or the TTU International Application, and create a RaiderConnect account. Graduate: apply online and pay by card.", "deadlines": "Graduate recommended dates: Fall and Summer Jan 15, Spring June 15. Undergraduate final dates are on the Important Dates page.", "application_fee": "$75 undergraduate. Graduate $75, rising to $100 after Jan 15 (summer), April 15 (fall) or Sept 15 (spring).", "documents": "High school transcripts, English test proof, and translations by an ATA member if needed. Official transcripts are due before the first semester. Graduate proof of finances is optional for admission.", "fees_link": "https://www.depts.ttu.edu/admissions/international/apply/newfirsttime.php", "sources": ["https://www.depts.ttu.edu/admissions/international/apply/newfirsttime.php", "https://www.depts.ttu.edu/gradschool/admissions/internationalprospectivestudents.php"]}$q$::jsonb, admission_link = $q$https://www.depts.ttu.edu/admissions/international/apply/newfirsttime.php$q$, admission_checked = '2026-11-13' where id = '6e4c2533-d391-44b1-b9e4-29d0aac99139' and country = 'United States';
update schools set admission_info = $q${"ug": "Complete the Cal State Apply application and choose a major (Undeclared is not allowed). Upload unofficial transcripts for every high school and your diploma.", "pg": "Official transcripts for all post-secondary study and degree certificates. Send a course-by-course evaluation from IERF or WES, or sealed official documents.", "english": "TOEFL iBT 80 (taken before Jan 21, 2026; new-scale score to be confirmed), IELTS 6.5, Duolingo 105, PTE 58. Some programs need higher scores. Scores must be from the last two years.", "how_to_apply": "Apply at Cal State Apply, pay the fee, then upload documents in my.SDSU. Admitted students send official transcripts before orientation.", "deadlines": "Undergraduate page lists no date; decisions come in spring. Graduate document deadline appears in your my.SDSU account.", "application_fee": "$70, not refundable.", "documents": "Unofficial transcripts, diploma, English test report, certified English translations for non-English records. Graduate: credential evaluation or sealed official records. The pages checked list no scholarships.", "fees_link": "https://admissions.sdsu.edu/international/first-years/steps-apply", "sources": ["https://admissions.sdsu.edu/international/first-years/steps-apply", "https://admissions.sdsu.edu/international/graduate/steps-apply"]}$q$::jsonb, admission_link = $q$https://admissions.sdsu.edu/international/first-years/steps-apply$q$, admission_checked = '2026-11-13' where id = 'ed259fc0-a708-40c7-84be-c5d8e3edbb3c' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen need ACT or SAT scores, official evaluated high school transcripts and English scores. Transfer students need evaluated college transcripts and a 2.5 GPA (2.8 for Architecture).", "pg": "Four-year bachelor's degree or equal. Some departments ask for GRE or GMAT. Check your program page.", "english": "Undergraduate: TOEFL iBT 79, PTE 53, IELTS 6.5. Graduate: TOEFL iBT 4.5 (new scale; 79 before Jan 21, 2026), IELTS 6.5, Duolingo 115. Some departments need higher.", "how_to_apply": "Apply online and send scores directly from the testing agency. Freshman scholarship applications go through the AUSOM system.", "deadlines": "Undergraduate Fall: Feb 1 freshman, July 1 transfer. Spring: Nov 1. Summer: Feb 1 freshman, May 1 transfer. Graduate: apply at least three months before term start. Freshman scholarship deadline Feb 12.", "application_fee": "$60 undergraduate, $70 graduate. Not refundable.", "documents": "Credential-evaluated transcripts (WES preferred), Affidavit of Financial Support and a bank letter in USD covering nine months of costs. Graduate: translated transcripts and an Official Statement of Finances.", "fees_link": "https://www.auburn.edu/admissions/prospective-students/international/", "sources": ["https://www.auburn.edu/admissions/prospective-students/international/", "https://graduate.auburn.edu/admissions/international-instructions.php"]}$q$::jsonb, admission_link = $q$https://www.auburn.edu/admissions/prospective-students/international/$q$, admission_checked = '2026-11-13' where id = '50ec5b8d-993c-4905-889d-9b46992e497c' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply through Cal State Apply. Freshmen send transcripts including first-semester Grade 12 grades.", "pg": "Transcripts with at least six semesters of grades, plus a diploma or degree certificate if already graduated. Deadlines vary by major.", "english": "Undergraduate: TOEFL iBT 61, IELTS 6.0, Duolingo 105, PTE 43. Graduate: TOEFL iBT 80, IELTS 6.5, Duolingo 115, PTE 58. May be waived with a qualifying US degree.", "how_to_apply": "Apply at CalState.edu/Apply, then upload documents in the International Admissions Document Portal.", "deadlines": "Fall: undergraduate apply by April 1 (documents April 15); graduate apply by March 15 (documents April 1). Spring: apply by Oct 1, documents Oct 15.", "application_fee": "Not stated on the pages checked.", "documents": "Official or unofficial transcripts from non-US schools. Applicants from India must include individual marksheets.", "fees_link": "https://www.csulb.edu/international/future-students/application-document-deadlines", "sources": ["https://www.csulb.edu/international/future-students/application-document-deadlines", "https://www.csulb.edu/international-education-global-engagement/future-students/english-language-requirement"]}$q$::jsonb, admission_link = $q$https://www.csulb.edu/international/future-students/application-document-deadlines$q$, admission_checked = '2026-11-13' where id = '6c6ca988-d351-4d11-b948-248326e5defb' and country = 'United States';
update schools set admission_info = $q${"ug": "3.0 GPA on academic courses, three years of secondary coursework, completed secondary school, and college-specific courses. SAT or ACT is not required unless you want academic scholarships, Tippie Direct Admission or Honors.", "pg": "Requirements depend on the program. Show a financial statement for one full year if you need F-1 or J-1 status.", "english": "Required; the pages checked give no scores. SAT or ACT can satisfy it for students schooled outside the US. Graduate rules vary by program.", "how_to_apply": "Apply on the University of Iowa admissions site. Test scores strongly help scholarship chances: ACT 26 or SAT 1230 and above are linked to larger merit awards.", "deadlines": "Not listed on the pages checked.", "application_fee": "Not listed on the pages checked.", "documents": "Transcripts showing graduation date or a diploma, SAT or ACT if required. Nursing and Medical Laboratory Science have extra rules.", "fees_link": "https://www.admissions.uiowa.edu/international/international-first-year-student-admission", "sources": ["https://www.admissions.uiowa.edu/international/international-first-year-student-admission", "https://grad.admissions.uiowa.edu/node/71"]}$q$::jsonb, admission_link = $q$https://www.admissions.uiowa.edu/international/international-first-year-student-admission$q$, admission_checked = '2026-11-13' where id = '77320007-e106-42a2-87eb-96b5b3d1ebe3' and country = 'United States';
update schools set admission_info = $q${"ug": "Core courses: 4 units of math, 3 natural science, 3 social science and 4 English or native language. Show English skills.", "pg": "Extra international rules apply: degree equivalency, transcripts, English proof, finances and visa forms. Submit at least 30 days before term start.", "english": "TOEFL iBT 79 (4.0 new scale) with subscores, IELTS 6.5, Duolingo 110, or UNL English Language Test 80. Some colleges need more. Students short of the level can join the Nebraska Intensive English Program.", "how_to_apply": "First-year applicants can use the Common App or Nebraska's application. Send scores electronically from the testing agency.", "deadlines": "Fall 2027: priority Nov 1, final May 1. Spring 2027: Dec 1. English score deadlines: Fall July 15, Spring Dec 1, Summer May 1.", "application_fee": "$45, paid online by card.", "documents": "Final secondary transcript signed and stamped by the principal, diploma, English scores. For the I-20: financial statement, bank statement of at least $53,922, passport page.", "fees_link": "https://admissions.unl.edu/apply/admission-requirements/international", "sources": ["https://admissions.unl.edu/apply/admission-requirements/international", "https://graduate.unl.edu/admissions/international-applicants"]}$q$::jsonb, admission_link = $q$https://admissions.unl.edu/apply/admission-requirements/international$q$, admission_checked = '2026-11-13' where id = '0e04aec7-ced7-4e08-bbf7-13e68101f68b' and country = 'United States';
update schools set admission_info = $q${"ug": "Open to non-US citizens. Send official transcripts, proof of English and a passport copy.", "pg": "US bachelor's equivalent, cumulative GPA 3.0, three recommendation letters and department approval. Some programs need the GRE.", "english": "Graduate: TOEFL iBT 75 (4 on the new scale), IELTS 6.5, Duolingo 105, PTE 56, iTEP 4.5. Waivers apply for degrees taught in English. Undergraduate scores are on a separate WSU page.", "how_to_apply": "Apply through the FutureCoug Portal. WSU admits on a rolling basis.", "deadlines": "Undergraduate priority: Fall April 15, Spring Nov 1, Summer Feb 1. Graduate dates are on the Graduate School deadlines page.", "application_fee": "$70 undergraduate, not refundable. A $500 enrollment and orientation fee comes after proof of finances is approved.", "documents": "Official transcripts, passport copy, English proof, and a Certificate of Finances before enrolling. Non-English records need translations.", "fees_link": "https://ip.wsu.edu/future-students/how-to-apply-undergraduate/", "sources": ["https://ip.wsu.edu/future-students/how-to-apply-undergraduate/", "https://gradschool.wsu.edu/?p=1185"]}$q$::jsonb, admission_link = $q$https://ip.wsu.edu/future-students/how-to-apply-undergraduate/$q$, admission_checked = '2026-11-13' where id = '6d40b3f9-222e-4962-8cec-6d2a90faab42' and country = 'United States';
update schools set admission_info = $q${"ug": "Official or certified secondary records with a US-equivalent credential evaluation. Required courses include 4 English, 4 math, 3 science, 3 social science and 2 world language. Check the current FSU page for test rules.", "pg": "Apply through the department. Non-US records need a course-by-course evaluation from a NACES member. GRE is waived for most master's programs through Fall 2026, except Business.", "english": "Graduate: TOEFL iBT 80 (taken before Jan 21, 2026), IELTS 6.5, Duolingo 125, PTE 55. Some departments need more. Level 8 at FSU's English center also counts.", "how_to_apply": "Apply online, then follow the I-20 steps after admission. A visa restriction notice applies to some countries, so read it before applying.", "deadlines": "Graduate priority international deadline: Jan 15; some programs are earlier.", "application_fee": "Graduate application fee cannot be waived. Amount not stated.", "documents": "Certified literal English translations, proof of degree and award date, official evaluation, and proof of finances for the first year.", "fees_link": "https://gradschool.fsu.edu/admissions/international-admissions", "sources": ["https://gradschool.fsu.edu/admissions/international-admissions", "https://admissions.fsu.edu/international/freshman"]}$q$::jsonb, admission_link = $q$https://gradschool.fsu.edu/admissions/international-admissions$q$, admission_checked = '2026-11-13' where id = 'cd673514-bb1a-4984-aab5-d2cd342ac134' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen need a high school GPA of 2.75 or higher; transfers need 2.0. Choose a specific major. No essay, recommendations or SAT/ACT needed.", "pg": "Not covered on the page; contact the SIU Graduate School.", "english": "TOEFL iBT 68, IELTS 6.0, Duolingo 95, PTE 47, iTEP Academic Plus 3.6, or SIU's CESL certificate. Conditional admission is possible with CESL.", "how_to_apply": "Apply online and upload documents. After admission, send a passport copy, financial statement and affidavit of support for the I-20.", "deadlines": "No deadline on the page checked. One term deferral is allowed before the term starts.", "application_fee": "$40, not refundable.", "documents": "Official transcripts with seal and English translation. Scans are accepted for admission; originals are due before or on arrival.", "fees_link": "https://siu.edu/international/admissions/", "sources": ["https://siu.edu/international/admissions/"]}$q$::jsonb, admission_link = $q$https://siu.edu/international/admissions/$q$, admission_checked = '2026-11-13' where id = 'd5afc8ba-1143-45bc-8059-8d42a9850e7f' and country = 'United States';
update schools set admission_info = $q${"ug": "About 34 college-prep courses including English, math, social science, science and a world language, with a B average or higher. Test-optional; submit SAT or ACT if you have it.", "pg": "Apply through the Graduate and Professional Admissions Application. TOEFL is normally required. Programs may add rules.", "english": "Undergraduate admission: TOEFL iBT 79, IELTS 6.5, Duolingo 115, PTE 53, or SAT Reading and Writing 560. Scores must be less than two years old. Beginning classes without English support needs TOEFL 100 or IELTS 7.5.", "how_to_apply": "Use the IU freshman application and check the country-specific transcript rules. Contact newtoiu@iu.edu for help.", "deadlines": "Not listed on the pages checked.", "application_fee": "Graduate fee $65 (IUPUI listing). Undergraduate fee not listed.", "documents": "Secondary transcripts and graduation credentials. Optional recommendation letter. Graduate: TOEFL results or an official statement of English ability.", "fees_link": "https://bloomington.iu.edu/admissions/apply/international/freshman/admission-standards.html", "sources": ["https://bloomington.iu.edu/admissions/apply/international/freshman/admission-standards.html", "https://bloomington.iu.edu/admissions/apply/international/english-proficiency.html", "https://bulletins.iu.edu/iu/gradschool/2025-2026/admission/international.shtml"]}$q$::jsonb, admission_link = $q$https://bloomington.iu.edu/admissions/apply/international/freshman/admission-standards.html$q$, admission_checked = '2026-11-13' where id = 'efe20401-910a-413e-9288-ae1577b06705' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year: US-style secondary school with at least a 2.50 GPA. Transfer: 30 quarter credits with a 2.25 GPA, or an associate degree with 2.00.", "pg": "Not covered on the page checked.", "english": "Admitted students must meet the English rule, usually with TOEFL, IELTS or PTE. Scores are on a separate PSU English page and were not confirmed here.", "how_to_apply": "Apply through Undergraduate International Admissions.", "fees_link": "https://pdx-mobile.smartcatalogiq.com/2026-2027/bulletin/admissions-requirements/international-students/admission-requirements-for-international-students", "sources": ["https://pdx-mobile.smartcatalogiq.com/2026-2027/bulletin/admissions-requirements/international-students/admission-requirements-for-international-students"]}$q$::jsonb, admission_link = $q$https://pdx-mobile.smartcatalogiq.com/2026-2027/bulletin/admissions-requirements/international-students/admission-requirements-for-international-students$q$, admission_checked = '2026-11-13' where id = '03b85b62-2433-4fc6-90b3-066e7a6211a1' and country = 'United States';
update schools set admission_info = $q${"ug": "Admission is based on GPA with SAT, ACT or CLT scores. Apply through the Common App.", "pg": "Not covered on the page checked.", "english": "First-time freshmen do not need TOEFL or IELTS for direct admission; they must meet the Florida college readiness rules, mostly SAT or ACT reading and English sub-scores.", "how_to_apply": "Apply on the Common App only. Do not also use the FIU portal. SAT/ACT fee waivers can be used.", "deadlines": "Not listed on the page checked.", "application_fee": "$30, not refundable.", "documents": "SAT, ACT or CLT scores, high school transcripts sent electronically by the school, and official translations for non-English records.", "fees_link": "https://admissions.fiu.edu/international/incoming-freshmen/", "sources": ["https://admissions.fiu.edu/international/incoming-freshmen/"]}$q$::jsonb, admission_link = $q$https://admissions.fiu.edu/international/incoming-freshmen/$q$, admission_checked = '2026-11-13' where id = '9b8e894c-13a7-4a71-a8d6-ed534bbc87a4' and country = 'United States';
update schools set admission_info = $q${"ug": "Transcripts from every high school and college attended, plus proof of English. SAT or ACT is not required but is preferred for freshman scholarships.", "pg": "Not covered on the pages checked.", "english": "Approved exam needed (TOEFL iBT, IELTS or Duolingo). Minimums vary by school or college.", "how_to_apply": "Apply online and pay by card or US bank account. Apply 6 to 12 months before your start term. Decisions begin Oct 1.", "deadlines": "No set application deadline. For freshman scholarships, send all materials by Dec 1.", "application_fee": "$65.", "documents": "Transcripts (unofficial first, official after admission), test reports, financial documents with an Affidavit of Support if sponsored, and a passport copy after admission.", "fees_link": "https://admissions.missouri.edu/apply/international/how-to-apply", "sources": ["https://admissions.missouri.edu/apply/international/how-to-apply", "https://admissions.missouri.edu/costs-aid/scholarships/international-student-scholarships"]}$q$::jsonb, admission_link = $q$https://admissions.missouri.edu/apply/international/how-to-apply$q$, admission_checked = '2026-11-13' where id = '0d6e6afb-fb14-4a1b-a77f-463842ee072a' and country = 'United States';
update schools set admission_info = $q${"ug": "Undergraduate page could not be read.", "pg": "Check your program for extra rules. Send international transcripts for evaluation to WES, ACEI or ECE. SJSU generally does not accept three-year bachelor's degrees.", "english": "Graduate: TOEFL, IELTS, PTE or Duolingo at your program's minimum, or a non-test option such as three years of full-time US study. Scores must be under two years old.", "how_to_apply": "Apply on Cal State Apply with your legal name as on your passport. International deadlines are earlier than domestic ones and are firm.", "deadlines": "Fixed by program and not listed on the page checked.", "application_fee": "Paid at submission, not refundable, no waivers. Amount not stated.", "documents": "Passport copy valid at least one year, SJSU Declaration of Finance with a bank letter dated within six months, official transcripts, and an evaluation sent directly by WES, ACEI or ECE.", "fees_link": "https://sjsu.edu/admissions/graduate/want-to-apply/international-steps-to-admission/index.php", "sources": ["https://sjsu.edu/admissions/graduate/want-to-apply/international-steps-to-admission/index.php"]}$q$::jsonb, admission_link = $q$https://sjsu.edu/admissions/graduate/want-to-apply/international-steps-to-admission/index.php$q$, admission_checked = '2026-11-13' where id = '284a7079-b0dd-433b-8993-99d9197abdda' and country = 'United States';
update schools set admission_info = $q${"ug": "Send secondary and any university transcripts with English translations and one recommendation letter. SAT or ACT is optional. Music and theatre applicants audition; studio art applicants send a portfolio.", "pg": "Full application with two or three recommenders and transcripts from all prior post-secondary schools. A maximum of 5 backlogs is accepted from international institutions.", "english": "Undergraduate: IELTS 6.5, Duolingo 120, PTE 59, TOEFL Essentials 8.5, LanguageCert 70, TOEFL iBT 87 before Jan 2026 (new-scale figure to be confirmed). Graduate: TOEFL iBT 80, IELTS 6.5, PTE 59, Duolingo 120.", "how_to_apply": "Undergraduate: apply through the Common App. Graduate: apply online; processing can take 5 to 7 business days.", "deadlines": "Undergraduate: Spring Oct 15, Early Action Nov 15, Regular Feb 1, official documents June 30. Graduate dates depend on the program.", "application_fee": "$65 for first-year applicants. Graduate $65 for degrees and $25 for certificates.", "documents": "Passport bio page copy, transcripts with translations, test scores sent by the testing agency, and official transcripts after admission.", "fees_link": "https://admissions.unh.edu/apply/international-students", "sources": ["https://admissions.unh.edu/apply/international-students", "https://gradschool.unh.edu/admissions/international-students"]}$q$::jsonb, admission_link = $q$https://admissions.unh.edu/apply/international-students$q$, admission_checked = '2026-11-13' where id = '378041e8-a129-4738-83c7-3daa1e691112' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the Go Vols application or the Common App (no separate international application). Send an essay, official secondary school records and proof of English. Architecture and Design, Nursing, Music and Engineering (including Computer Science) also need ACT or SAT scores and other materials.", "english": "TOEFL iBT 79 (tests before Jan 21, 2026), IELTS 6.5, Duolingo 110, PTE 53, SAT Reading and Writing 540, ACT English 21. Some students are exempt, for example with US high school or approved English-language citizenship.", "how_to_apply": "Apply online through Go Vols or the Common App. Students who already attended college must apply as transfer students. The application fee cannot be waived for international applicants.", "deadlines": "Fall: Early Action Nov 1 (documents Nov 15), Regular Decision Jan 5 (documents Jan 20). Spring: Oct 1. Summer: Mar 15.", "application_fee": "$75, nonrefundable, no waiver for international applicants", "documents": "Official secondary school transcripts, diploma or certificates sent from the school or ministry, with certified English translation if needed. Proof of English. UT states it does not provide fully funded scholarships for international students; they are considered for the same scholarships as out-of-state students.", "fees_link": "https://admissions.utk.edu/undergraduate-tuition-aid/", "sources": ["https://admissions.utk.edu/apply/international-students/", "https://admissions.utk.edu/undergraduate-tuition-aid/", "https://admissions.utk.edu/undergraduate-application/international-information/"]}$q$::jsonb, admission_link = $q$https://admissions.utk.edu/undergraduate-tuition-aid/$q$, admission_checked = '2026-11-13' where id = '1604b05f-2acf-4a88-8c8f-b5b4d90d555b' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year students need secondary school records (expected GPA 2.75 on a 4.0 scale). Transfer students need college transcripts evaluated by a NACES service and expected GPA 2.0 or higher.", "pg": "Completed Graduate School application, official transcripts for all undergraduate and graduate work, passport copy, degree certificate, three letters of reference and a statement of purpose.", "english": "Undergraduate: TOEFL iBT 71 (before Jan 21, 2026) or 3.5 (after), IELTS 6.0, PTE 50, Duolingo 105, or ELS Level 112. Graduate: IELTS 6.0, TOEFL iBT 4.0 (new scale), Duolingo 110, or ELS Level 112.", "how_to_apply": "Apply online as an international student and pay the fee. The fee is not waived for any reason. UND's international pages do not name a specific international scholarship.", "deadlines": "Undergraduate first-year: Fall June 15, Spring Nov 15, Summer Mar 15. Graduate: Fall May 1, Spring Sept 1, Summer Feb 1 (some programs set their own dates).", "application_fee": "$35, nonrefundable, not waived", "documents": "Official transcripts for all secondary schools attended (translated if not in English), passport copy. Graduate also needs reference letters and statement of purpose.", "fees_link": "https://und.edu/admissions/international/requirements-application.html", "sources": ["https://und.edu/admissions/international/requirements-application.html", "https://und.edu/admissions/international/index.html"]}$q$::jsonb, admission_link = $q$https://und.edu/admissions/international/requirements-application.html$q$, admission_checked = '2026-11-13' where id = '8b16a204-8101-4292-ac61-f6af5a453b4e' and country = 'United States';
update schools set admission_info = $q${"ug": "Proof of English is required for all merit scholarships. CMU must check financial support before issuing the I-20 (extra $5,000 per dependent spouse and $2,500 per dependent child). Transfer students need at least 24 college credits for scholarships.", "pg": "Apply through CMU graduate admissions. Some tuition awards need undergraduate GPA 3.0 and strong test scores.", "english": "The page requires proof of English but does not list minimum scores for undergraduates. The Out-of-State Tuition Merit Award for graduates needs TOEFL iBT 100 or IELTS 7.", "how_to_apply": "Apply to CMU as an international student. Merit scholarships are considered automatically at application, with no separate application or essay. Students sponsored by their home country are not eligible for the merit awards.", "documents": "Proof of English proficiency and financial verification for the I-20. International student costs for 2026-27 are estimated at about $41,246 for 9 months.", "fees_link": "https://www.cmich.edu/international-admissions/undergraduate/cost-scholarships", "sources": ["https://www.cmich.edu/international-admissions/undergraduate/cost-scholarships", "https://cmich.edu/admissions-aid/international-students/scholarships/international-scholarships", "https://WWW.CMICH.EDU/admissions-aid/international-students/scholarships/graduate-scholarships"]}$q$::jsonb, admission_link = $q$https://www.cmich.edu/international-admissions/undergraduate/cost-scholarships$q$, admission_checked = '2026-11-13' where id = '6b2363d9-0f6e-4ad5-9e56-f3b47ceebad0' and country = 'United States';
update schools set admission_info = $q${"ug": "Global Select scholarship page says undergraduates need a GPA of 3.0 out of 4.0 or equivalent for the discount. SAT and ACT scores are not used for it.", "pg": "Graduate applicants need a GPA of 3.3 out of 4.0 or equivalent for the Global Select discount.", "english": "Undergraduate full-time: TOEFL iBT 72 (before Jan 21, 2026) or 4 (after), IELTS 6.0, Duolingo 105, PTE 49, or WSU English Proficiency Exam 80. Graduate minimums are on a separate WSU page.", "how_to_apply": "Apply for a degree program at WSU and answer the scholarship question on the admission application. The Global Select award is automatic at admission and renews until the program ends.", "documents": "Not confirmed on the pages read.", "fees_link": "https://wichita.edu/admissions/international/undergraduate/globalselect.php", "sources": ["https://wichita.edu/admissions/international/undergraduate/globalselect.php", "https://www.wichita.edu/admissions/international/toefl_ielts_req.php"]}$q$::jsonb, admission_link = $q$https://wichita.edu/admissions/international/undergraduate/globalselect.php$q$, admission_checked = '2026-11-13' where id = '27e271e6-aa47-4d96-8552-15d86f2ec4f7' and country = 'United States';
update schools set admission_info = $q${"ug": "UIC Global pathway tracks: International Direct needs GPA 3.0 (3.5 for Computer Science, Data Science and CS + Design). Academic Accelerator and Extended Accelerator need GPA 2.5. GCE A-Level applicants are reviewed on secondary GPA and number of A-levels (STEM and business need Math as one A-level).", "english": "International Direct: IELTS 6.5 (no part below 6.0) or TOEFL 80 (no part below 16). Academic Accelerator: IELTS 5.5 or TOEFL 68. Extended Accelerator: IELTS 5.0 or TOEFL 60.", "how_to_apply": "Apply through UIC Global to the track that fits your GPA and English level. Program length is 2 to 3 semesters before moving to the full degree.", "documents": "High school transcripts and any college transcripts, passport copy, English test scores.", "fees_link": "https://global.uic.edu/undergraduate-admissions/", "sources": ["https://global.uic.edu/undergraduate-admissions/"]}$q$::jsonb, admission_link = $q$https://global.uic.edu/undergraduate-admissions/$q$, admission_checked = '2026-11-13' where id = '3779e84b-3339-4da8-8d38-861246ba1049' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply through the Common App or Coalition on Scoir. Pick up to two majors, write an essay (up to 650 words) and a short answer on why you chose your program. Studio majors (Architecture, Art and Design, etc.) need a portfolio.", "english": "For full admission: TOEFL iBT 80 (each section 18) before Jan 21, 2026 or 4.5 after, IELTS 6.5 (each section 6.0), Duolingo 110, PTE 58, TOEFL Essentials 9.0. Conditional admission is possible with lower scores through the Intensive English Program.", "how_to_apply": "Apply online. International applicants are not eligible for financial aid. A limited number of competitive merit scholarships exist; admitted students apply through PACKASSIST, which opens after admission.", "deadlines": "Early Action Nov 1. Regular Decision Jan 15. Portfolio majors: Nov 1.", "application_fee": "$100, nonrefundable, no fee waivers accepted", "documents": "Official secondary transcripts with English translation, English proof, and financial proof for F-1 or J-1 (bank statement within 6 months). Enrollment deposit $300 (full admission) or $200 (conditional).", "fees_link": "https://admissions.ncsu.edu/apply/international/first-year/", "sources": ["https://admissions.ncsu.edu/apply/international/first-year/"]}$q$::jsonb, admission_link = $q$https://admissions.ncsu.edu/apply/international/first-year/$q$, admission_checked = '2026-11-13' where id = 'a31961bd-5aee-479e-a05c-0d7d43e741c8' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the USC Application or the Common App. Send secondary transcripts and an essay. SAT and ACT are optional for 2027 entry.", "english": "TOEFL iBT 77, IELTS 6.5, PTE 53, Duolingo 115, SAT Reading and Writing 560, ACT English 22. Exempt: applicants from countries where English is the main language of instruction and US high school graduates. Those below the score can use the English Programs for Internationals or the International Accelerator Program.", "how_to_apply": "Apply online. The Honors College round is considered for Top Scholar awards. The page does not list scholarships made only for international students.", "deadlines": "Early Action Oct 15 (documents Nov 1). Honors College Nov 15 (documents Dec 1). Regular Decision Dec 1 (documents Jan 15).", "application_fee": "$100, nonrefundable", "documents": "Completed application, official transcripts from every secondary school (certified English translation if needed), English proficiency score unless exempt.", "fees_link": "https://caravel.sc.edu/about/offices_and_divisions/undergraduate_admissions/apply/for_international_students", "sources": ["https://caravel.sc.edu/about/offices_and_divisions/undergraduate_admissions/apply/for_international_students"]}$q$::jsonb, admission_link = $q$https://caravel.sc.edu/about/offices_and_divisions/undergraduate_admissions/apply/for_international_students$q$, admission_checked = '2026-11-13' where id = 'f2970cc8-84a5-4386-882d-5fc351b17585' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen from schools outside the US need complete transcripts, proof of graduation and about a 2.5 GPA on a 4.0 scale. SAT or ACT is optional. Transfers need a 2.0 GPA.", "pg": "Graduate requirements are on the SF State Graduate Studies website (not confirmed here).", "english": "TOEFL iBT 61, IELTS 6.0, PTE 45, SAT Reading and Writing 550, ACT English 22, or IB English A Higher Level 4. Exempt after 3 years at a US high school or 3 years in listed English-instruction countries.", "how_to_apply": "Apply through Cal State Apply. SF State says scholarships are only for continuing and currently enrolled international students, and international students cannot get US federal or state aid, so no scholarship is listed for new applicants.", "deadlines": "Fall: priority Nov 30, final May 1 (F-1). Spring: priority Aug 31, final Sept 30. Impacted majors need the priority date.", "application_fee": "$55, nonrefundable", "documents": "Transcripts and proof of graduation with certified translation, passport copy, Financial Affidavit and proof of funds for the I-20.", "fees_link": "https://www.sfsu.edu/public_html/apply/international.html", "sources": ["https://www.sfsu.edu/public_html/apply/international.html"]}$q$::jsonb, admission_link = $q$https://www.sfsu.edu/public_html/apply/international.html$q$, admission_checked = '2026-11-13' where id = '1c4f32fd-f7c7-478e-87b9-a0bd17025a39' and country = 'United States';
update schools set admission_info = $q${"ug": "International freshmen have no college coursework (or fewer than 15 credit hours) and meet English requirements. Some majors need extra GPA, courses, or SAT or ACT.", "english": "TOEFL iBT 4.0 (new scale), IELTS 6.5, or Duolingo 105. Also accepted: US degree, equivalent from an English-speaking country, or UH Intensive English Level 6.", "how_to_apply": "Apply with the Common App or ApplyTexas and write a short essay. Send test scores from the testing agency and official school records for grades 9 to 12. After admission, send the I-20 documents.", "deadlines": "Fall 2027: scholarship priority Nov 2, 2026 (supporting documents Nov 9); regular May 3, 2027. Spring 2027: Nov 2, 2026. Summer 2027: Apr 2, 2027.", "application_fee": "$90 for international applicants", "documents": "Official secondary records for years 9 to 12 with certified literal English translation, test scores, and for the I-20: financial support form, bank statement (minimum balance $43,110), passport page, international address form.", "fees_link": "https://uh.edu/undergraduate-admissions/apply/international/international-freshman", "sources": ["https://uh.edu/undergraduate-admissions/apply/international/international-freshman", "https://uh.edu/apply/international/international-undergraduate-scholarship-flyer.pdf"]}$q$::jsonb, admission_link = $q$https://uh.edu/undergraduate-admissions/apply/international/international-freshman$q$, admission_checked = '2026-11-13' where id = '57053396-1cbb-47ad-86a5-bc922fb4d9ca' and country = 'United States';
update schools set admission_info = $q${"ug": "Use the Common App if still in your final secondary year, otherwise the UToledo application (International Application). Most programs need transcripts and English proof. Engineering needs math proof (ACT 22, SAT math 540 or ALEKS 76 for Engineering Science).", "english": "English proof is required for most programs. Minimum scores are on UToledo's English Language Proficiency page (not read).", "how_to_apply": "Apply online as an international applicant. The International Rocket Award is given at admission with no other application.", "deadlines": "Fall 2027 freshman: July 1, 2027. Transfers already in the US: Aug 1, 2027. Later applications may be moved to the next term.", "application_fee": "Not stated. ALEKS math test is $20 for students without ACT or SAT.", "documents": "Transcripts from all schools, list of all schools attended, English proof, math proof for engineering.", "fees_link": "https://www.utoledo.edu/admission/international/tuition/", "sources": ["https://www.utoledo.edu/admission/international/how-to-apply.html", "https://www.utoledo.edu/admission/international/tuition/"]}$q$::jsonb, admission_link = $q$https://www.utoledo.edu/admission/international/tuition/$q$, admission_checked = '2026-11-13' where id = 'bd2bb2b5-451b-4a52-80a9-d210952a42af' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year: 3.0 GPA, or SAT 1120, or ACT 22. Transfer: 2.5 GPA in 24 or more transferable credits.", "english": "Proof of English is required. Scores are listed on a separate UNLV English Proficiency page.", "how_to_apply": "Apply with the UNLV application or the Common App. Fill in the Institutional Aid Application to be considered for institutional grants and scholarships. The page names no specific international scholarships.", "deadlines": "Fall first-year priority Nov 15, final June 1. Fall transfer priority Mar 15, final July 1. Spring Dec 1.", "application_fee": "$95, nonrefundable", "documents": "High school transcript with certified translation, college transcripts if any, English proof. After admission: Confidential Financial Certification and a bank letter.", "fees_link": "https://www.unlv.edu/admissions/international/undergraduate", "sources": ["https://www.unlv.edu/admissions/international/undergraduate"]}$q$::jsonb, admission_link = $q$https://www.unlv.edu/admissions/international/undergraduate$q$, admission_checked = '2026-11-13' where id = 'd2524402-14b1-471f-915f-1784e99231f7' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year students self-report their high school record through STARS and list two intended majors. Test scores are optional. Transfer applicants need 30 transferable credits and a GPA of at least 2.5.", "english": "Duolingo 105, TOEFL iBT 80 (or 4 on the new 2026 scale), IELTS 6.5 (at least 6.0 in each part). English can be waived if English is your primary or an official language.", "how_to_apply": "Apply online. Clemson states there are no scholarships for international undergraduates, so none is listed. Sister-State agreements give in-state tuition to citizens of some places (not Ghana).", "deadlines": "Fall: May 1. Spring: Oct 1 (I-20 documents by June 1 and Nov 1).", "application_fee": "$70, nonrefundable", "documents": "STARS self-reported transcript (official copy before enrollment), proof of funds for the full time at Clemson, health insurance with at least $50,000 coverage.", "fees_link": "https://www.clemson.edu/admissions/undergraduate-admissions/apply/international.html", "sources": ["https://www.clemson.edu/admissions/undergraduate-admissions/apply/international.html"]}$q$::jsonb, admission_link = $q$https://www.clemson.edu/admissions/undergraduate-admissions/apply/international.html$q$, admission_checked = '2026-11-13' where id = 'd26091c8-17e0-4849-9a2e-70034e545cb5' and country = 'United States';
update schools set admission_info = $q${"ug": "Upload transcripts for all secondary and university study with English translation if needed. SAT or ACT is not required. New international students are not admitted for summer.", "pg": "Graduate funding comes from the academic program. Documents are the same upload process.", "english": "Proof of English is required if English is not your first language. Alternatives: 18 months of full-time university study in English, or the last two years of secondary school in English. Test minimums are on a separate UWM page.", "how_to_apply": "Apply online. Undergraduates pay no application fee. Admitted students pay a $200 International Student Processing Fee and bring original documents on arrival.", "deadlines": "Outside the US: Fall June 1, Spring Dec 1. Inside the US: Fall Aug 1.", "application_fee": "No application fee for undergraduates; $200 processing fee after admission", "documents": "Transcripts, degree certificates, English proof. Original documents shown on arrival.", "fees_link": "https://uwm.edu/cie/international-admissions/cost-scholarships/", "sources": ["https://uwm.edu/cie/international-admissions/bachelors-application/", "https://uwm.edu/cie/international-admissions/cost-scholarships/", "https://uwm.edu/cie/?p=160"]}$q$::jsonb, admission_link = $q$https://uwm.edu/cie/international-admissions/cost-scholarships/$q$, admission_checked = '2026-11-13' where id = '3e721dec-e1b4-42f5-ae38-fddd7ada9d6e' and country = 'United States';
update schools set admission_info = $q${"ug": "Common App with UMass questions, official high school transcript (grades 9 to 11) or secondary exam results, one letter of recommendation, and English proof. SAT or ACT is optional.", "english": "Proof of English is required for non-native speakers. Scores are on a separate UMass English Language Proficiency page.", "how_to_apply": "Apply through the Common App. International students cannot be admitted for spring unless currently at a US high school on a valid student visa.", "deadlines": "Early Action Nov 5. Regular Decision Jan 15.", "application_fee": "$85, cannot be waived", "documents": "Transcripts, one recommendation letter, English proof.", "fees_link": "https://www.umass.edu/admissions/undergraduate-admissions/apply/international-students/international-admissions", "sources": ["https://www.umass.edu/admissions/undergraduate-admissions/apply/international-students/international-first-year", "https://www.umass.edu/admissions/undergraduate-admissions/apply/international-students/international-admissions"]}$q$::jsonb, admission_link = $q$https://www.umass.edu/admissions/undergraduate-admissions/apply/international-students/international-admissions$q$, admission_checked = '2026-11-13' where id = '4b3c56a0-c02a-4510-b4fc-d625eb4e4873' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the Common App. Send transcripts, a 250 to 650 word essay and English scores. SAT and ACT are not required. A GPA of 3.0 or higher with a steady or rising trend is general guidance.", "pg": "Apply through the CSU Graduate School. Departments set deadlines. Applications open mid-September for summer and fall and mid-February for spring.", "english": "TOEFL, IELTS Academic or Duolingo accepted. No fixed minimum on the page; Fall 2024 admits had middle ranges of IELTS 6 to 7 and TOEFL 85 to 101. Conditional admission with the Intensive English Program is possible.", "how_to_apply": "Apply online. Admitted students are considered for international scholarships automatically, with no separate application.", "deadlines": "Fall: Early Action Nov 15, Regular Jan 15. Spring: Nov 1.", "application_fee": "$65, or apply for a fee waiver", "documents": "Transcripts with certified English translation, essay, English scores, passport and proof of funds for the I-20.", "fees_link": "https://admissions.colostate.edu/apply/international-freshmen", "sources": ["https://admissions.colostate.edu/apply/international-freshmen", "https://thehub.colostate.edu/financial-aid/international-student-scholarships/", "https://international.colostate.edu/iec/apply"]}$q$::jsonb, admission_link = $q$https://admissions.colostate.edu/apply/international-freshmen$q$, admission_checked = '2026-11-13' where id = '6601986b-a372-4079-99a4-050a20641ddc' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the Common App or Mason's own application. Send certified official transcripts from all secondary schools and leaving exam results. SAT or ACT is optional. Two recommendation letters are suggested and a personal statement is encouraged.", "english": "Non-native English speakers must meet Mason's English proficiency requirement. Scores are on a separate Mason page (not read).", "how_to_apply": "Apply online with the application fee. Scholarship terms on the page found for the #YouAreWelcomeHere Scholarship were from an older year, so no scholarship is listed.", "application_fee": "Required, amount not stated on the page", "documents": "Certified official secondary transcripts with certified English translation, leaving certificate results.", "fees_link": "https://www.gmu.edu/freshman/requirements/international", "sources": ["https://www.gmu.edu/freshman/requirements/international"]}$q$::jsonb, admission_link = $q$https://www.gmu.edu/freshman/requirements/international$q$, admission_checked = '2026-11-13' where id = '948a2d4c-a36b-49c2-9551-5c3cded4dd0b' and country = 'United States';
update schools set admission_info = $q${"ug": "At least 3 units of math (including Algebra I and II) and 2 units of lab science. Admitted students typically have a B+ average. Submit a STARS self-reported record or upload transcripts and exam results. SAT and ACT are not required.", "english": "TOEFL iBT 80 (no section below 16) for tests on or after Jan 21, 2026, IELTS 6.5, PTE 59, Duolingo 115, Cambridge 176, SAT Reading and Writing 550, ACT English 24. Scores must be from the last 2 years. Those below the minimum may join the Language and Culture Institute first.", "how_to_apply": "Apply through the Common App. The page does not describe scholarships for international students.", "deadlines": "Academic materials and English results: Early Action Dec 1, Regular Decision Jan 24. Transfer English results: Mar 15 (Fall), Oct 15 (Spring).", "documents": "STARS record or transcripts and all exam results, English test report sent by the testing body (CEEB code 5859).", "fees_link": "https://vt.edu/admissions/international/requirements.html", "sources": ["https://vt.edu/admissions/international/requirements.html"]}$q$::jsonb, admission_link = $q$https://vt.edu/admissions/international/requirements.html$q$, admission_checked = '2026-11-13' where id = '3da0c117-f568-46f0-884f-481b60e4c992' and country = 'United States';
update schools set admission_info = $q${"ug": "New undergraduates need a 2.75 GPA, or an equivalent school record with ACT 21, SAT 1060, or top 20 percent of class. Foreign transcripts need a NACES evaluation. Transfer students need a 2.0 GPA and 30 credits.", "pg": "See the NMSU Graduate School catalog (not listed on the page read).", "english": "Undergraduate: TOEFL iBT 68, IELTS 6.0, Duolingo 95. All admitted international students also take the English Language Placement Test.", "how_to_apply": "Apply online as an international student. New undergraduates cannot be admitted for summer.", "deadlines": "Fall: application started by July 1, documents by July 15. Spring: application by Nov 15, documents by Dec 1.", "documents": "After admission: passport, bank letter (last 3 months, covering one year), Affidavit of Support. Foreign Credential Evaluation from a NACES member.", "fees_link": "https://catalogs.nmsu.edu/nmsu/international-students/", "sources": ["https://catalogs.nmsu.edu/nmsu/international-students/"]}$q$::jsonb, admission_link = $q$https://catalogs.nmsu.edu/nmsu/international-students/$q$, admission_checked = '2026-11-13' where id = '679e9944-bda4-4755-b548-ca9ed371ac58' and country = 'United States';
update schools set admission_info = $q${"ug": "Official secondary transcripts and a NACES credential evaluation sent to Akron. SAT or ACT is test-optional. Transfers need college transcripts and proof of secondary school graduation.", "pg": "Graduate applicants need a course-by-course NACES evaluation of foreign college credits (TEC, WES, ECE or IEE). Deadlines are on a separate UA page.", "english": "TOEFL iBT 71, IELTS 6.0, SAT Reading and Writing 500, ACT English 18, Duolingo 95, Cambridge 169, PTE 48. Scores are valid 2 years. Waived with 3 or more years of high school in English.", "how_to_apply": "Apply online. Admission is rolling. First-time international students typically cannot start in summer.", "deadlines": "Fall June 1. Spring Oct 1.", "documents": "Official transcripts, credential evaluation (UA code for TOEFL 1829), English scores, passport copy.", "fees_link": "https://uakron.edu/international/scholarships", "sources": ["https://fye.uakron.edu/international/apply", "https://uakron.edu/international/scholarships", "https://www.uakron.edu/international/apply/evaluation"]}$q$::jsonb, admission_link = $q$https://uakron.edu/international/scholarships$q$, admission_checked = '2026-11-13' where id = 'a062bfdb-874a-4424-82b9-cbba3e172da8' and country = 'United States';
update schools set admission_info = $q${"ug": "International first-time freshmen need a GPA of 3.0 on a 4.0 scale (a B average) and must meet the English requirement.", "english": "IELTS 6.0, TOEFL iBT 61 (old) or 3.5 (new), PTE 50, Duolingo 95, Cambridge C1 172. No test needed after 3 years of high school in English (US or listed countries).", "how_to_apply": "Apply through Cal State Apply. The page does not mention scholarships.", "deadlines": "Spring 2027: apply July 1 to Oct 31, documents by Nov 15. Fall 2027: apply Aug 1 to May 15, documents by June 15.", "application_fee": "$70, credit or debit card only", "documents": "Official school records in the original language with official English translations, English test result, Affidavit of Financial Support with bank statement, passport photo page.", "fees_link": "https://www.csun.edu/admissions-financial-aid/how-to-apply/international-students/international-first-time-freshmen", "sources": ["https://www.csun.edu/admissions-financial-aid/how-to-apply/international-students/international-first-time-freshmen"]}$q$::jsonb, admission_link = $q$https://www.csun.edu/admissions-financial-aid/how-to-apply/international-students/international-first-time-freshmen$q$, admission_checked = '2026-11-13' where id = 'afda5b05-98cb-4d96-a0b4-092cab29c0f7' and country = 'United States';
update schools set admission_info = $q${"ug": "Send certified official academic records, national exam results (such as WASSCE, I/GCSE or A-Levels), English proof, financial statement and passport copy. SAT and ACT are not required.", "english": "TOEFL iBT 80 (or 4.0 new scale), IELTS 6.5, Cambridge 180, PTE 58, Duolingo 115, SAT Reading and Writing 580, ACT English 23, WASSCE English B3. Scores must be within 2 years of the start date.", "how_to_apply": "Apply online. All international first-year applicants are reviewed automatically for scholarships. Federal aid is not available to non-US citizens and CU does not offer direct loans.", "deadlines": "Documents for automatic scholarship consideration: Jan 15 (first-year).", "documents": "Certified transcripts with certified literal English translation, English proof, financial statement, passport copy.", "fees_link": "https://www.colorado.edu/admissions/faqs/international", "sources": ["https://www.colorado.edu/admissions/faqs/international", "https://www.colorado.edu/admissions/process/international/plan/english-proficiency"]}$q$::jsonb, admission_link = $q$https://www.colorado.edu/admissions/faqs/international$q$, admission_checked = '2026-11-13' where id = '2b3d511b-acf1-40b4-97ae-083309d176ed' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the SUNY Application or Common App. Send transcripts, one recommendation (freshmen), essay and the International Student Financial Statement. SAT and ACT are optional.", "english": "TOEFL iBT 70 (4 on new scale), IELTS 6.0, PTE 50, Duolingo 95, Cambridge B2. Required if you attended high school outside the US and English is not your native language. Conditional admission is possible with an Intensive English program.", "how_to_apply": "Apply online with the fee. Students are reviewed for Global Excellence Scholarships.", "deadlines": "Early Action Nov 1. Regular Admission Mar 1 (rolling review).", "application_fee": "Required, amount not stated on the page", "documents": "Transcripts with certified translation, financial statement with bank statement and passport copy, one recommendation letter for freshmen.", "fees_link": "https://www.albany.edu/international-admissions/apply-international-undergraduate-student", "sources": ["https://www.albany.edu/international-admissions/apply-international-undergraduate-student"]}$q$::jsonb, admission_link = $q$https://www.albany.edu/international-admissions/apply-international-undergraduate-student$q$, admission_checked = '2026-11-13' where id = '791e0896-a736-45e9-af29-b477faf09efc' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen need the equivalent of a US high school diploma and must meet freshman standards. Transfers: 2.0 GPA (14 or fewer hours), 2.5 GPA (15 to 29 hours), 2.25 GPA (30 or more hours).", "english": "TOEFL iBT 78 (each section 19), IELTS 6.5 (each section 6.0), Duolingo 105, PTE 52, SAT Reading and Writing 520, ACT English 21, WASSCE B3. Scores no older than 2 years.", "how_to_apply": "Apply with the TXST application, Common App or ApplyTexas and pay the fee. Texas State's international scholarship page lists awards for Mexico (TAMS) and the Western Hemisphere (Good Neighbor), which do not cover Ghana, so none is listed.", "deadlines": "Set by term on the TXST priority dates page. Apply by the priority date to meet the scholarship deadline.", "application_fee": "$90, nonrefundable, no waivers for international students", "documents": "Secondary transcripts with all courses and marks, graduation or leaving exam results (certified by the school or a US embassy), certified translation. WAEC candidates must give a scratch card or results checker by the closing date.", "fees_link": "https://admissions.txst.edu/future-students/international/admissions-requirements", "sources": ["https://admissions.txst.edu/future-students/international/admissions-requirements", "https://finaid.txst.edu/scholarships/international.html"]}$q$::jsonb, admission_link = $q$https://admissions.txst.edu/future-students/international/admissions-requirements$q$, admission_checked = '2026-11-13' where id = 'ea1d56d7-6195-466d-9147-0ebc84f6164d' and country = 'United States';
