update schools set admission_info = $q${"ug": "Judged on academic preparation, past performance and English. Transfers need at least 24 semester credits at one school. International students are not eligible for conditional admission.", "english": "TOEFL 3.5 (new scale), IELTS 5.5, Duolingo 90, PTE 44, SAT Reading and Writing 490, ACT 18. WAEC grade B3 is accepted. Citizens of listed countries (such as Nigeria and South Africa) are waived.", "how_to_apply": "Apply, pay the fee, send passport page, transcripts and English proof. SAT or ACT is optional.", "deadlines": "Fall: March 1. Spring: October 1. Rolling after if seats remain.", "application_fee": "$25", "documents": "Passport photo page, transcripts, English proof, optional SAT or ACT.", "fees_link": "https://www.sdstate.edu/admissions/international-first-time-undergraduate-admissions", "sources": ["https://www.sdstate.edu/admissions/international-first-time-undergraduate-admissions", "https://www.sdstate.edu/international-affairs/funding-your-education"]}$q$::jsonb, admission_link = $q$https://www.sdstate.edu/admissions/international-first-time-undergraduate-admissions$q$, admission_checked = '2026-11-13' where id = '08013c68-371d-4cc0-b685-9715924efbad' and country = 'United States';
update schools set admission_info = $q${"ug": "Complete A to G subjects with C- or better. For students who graduated abroad: 3.00 GPA on a 4.00 scale in the last 3 years of high school, in a college-prep track.", "english": "Required if under 3 years of English-only high school. TOEFL, IELTS, PTE and Duolingo accepted. Minimum scores are on a separate page.", "how_to_apply": "Apply through Cal State Apply.", "deadlines": "Fall 2027 filing: Oct 1, 2026 to Mar 31, 2027. Enrollment deposit due May 1.", "application_fee": "Not stated on the page", "documents": "Official transcripts with grading scale covering coursework through Fall 2026, English test scores. $100 deposit.", "fees_link": "https://www.calstatela.edu/admissions/international-freshman-admission", "sources": ["https://www.calstatela.edu/admissions/international-freshman-admission"]}$q$::jsonb, admission_link = $q$https://www.calstatela.edu/admissions/international-freshman-admission$q$, admission_checked = '2026-11-13' where id = '4c2c85b0-7e50-4ebb-a9d8-357ba32c66d7' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the Common App. First-time students send SAT, ACT or CLT scores. High school records need a NACES evaluation.", "english": "Required if English is not your first language. Minimum scores are on a separate page. A Conditional Admissions Track exists for lower scores.", "how_to_apply": "Apply on the Common App, then send scores and the NACES-evaluated transcript.", "deadlines": "Freshman Fall: Mar 13. Transfer Fall: Jul 1. International scholarship: Fall Jan 15 priority, Mar 15 regular. Spring Aug 15 priority, Oct 15 regular.", "application_fee": "$30, non-refundable", "documents": "NACES course-by-course evaluation, SAT or ACT, English scores. FAU codes: SAT 5229, ACT 0729.", "fees_link": "https://www.fau.edu/admissions/international/", "sources": ["https://www.fau.edu/admissions/international/", "https://www.fau.edu/admissions/international/scholarships/"]}$q$::jsonb, admission_link = $q$https://www.fau.edu/admissions/international/$q$, admission_checked = '2026-11-13' where id = '8a982215-8e79-4473-a22a-5aa43d7bbb0a' and country = 'United States';
